(globalThis.TURBOPACK||(globalThis.TURBOPACK=[])).push(["object"==typeof document?document.currentScript:void 0,21086,16095,e=>{"use strict";let a=[{id:"italian",name:"Italian Game",eco:"C50–C54",side:"white",order:1,tagline:"The classical way to learn attacking chess with White",summary:"After 1.e4 e5 2.Nf3 Nc6 3.Bc4, White develops naturally, aims the bishop at Black's weakest square (f7), and castles quickly. The Italian teaches every core opening principle while keeping real attacking chances — it is the single best first opening for improving players.",whyPlayIt:["Every move follows a principle you can name: center, development, king safety.","The bishop on c4 eyes f7 — the one square only Black's king defends — so tactical themes appear early and teach you to calculate.","The modern d3 setups (the 'Giuoco Pianissimo') give you a rich middlegame plan you can play for years, all the way to master level."],keyPrinciples:["Fight for the center with e4 and (eventually) d4 or the slow c3+d3 build.","Develop knights before bishops, and develop toward the center.","Castle before move 8 in almost every line.","Don't grab material before finishing development."],commonMistakes:[{mistake:"Playing Ng5 too early hunting the f7 fork without backup",why:"After 3...Nf6 4.Ng5?! d5! Black returns the pawn structure blow — 4.Ng5 is a real weapon but only if you know the theory. As a learner, 4.d3 keeps every advantage of the position without memorization."},{mistake:"Blocking the c-pawn with an early Nc3 in c3 lines",why:"The whole point of the modern Italian is c2-c3 preparing d3-d4 later. Nc3 gives that plan away; the knight belongs on d2 heading to f1-g3."},{mistake:"Trading the c4 bishop for a knight without reason",why:"That bishop is your best attacker. Meet ...Na5 ideas with Bb3 or retreat rather than trading it off cheaply."}],lines:[{id:"italian-pianissimo",difficulty:1,name:"Giuoco Pianissimo (Main Line)",description:"The modern main line: White builds slowly with c3 and d3, castles, and keeps all the pieces on for a long strategic fight. This is what top grandmasters actually play.",side:"white",moves:[{san:"e4",explanation:"Stake a claim in the center and open lines for the queen and king's bishop. The most principled first move.",principle:"Control the center"},{san:"e5",explanation:"Black mirrors, claiming an equal share of the center."},{san:"Nf3",explanation:"Develop with a threat — the knight attacks e5. Knights before bishops.",principle:"Develop with threats"},{san:"Nc6",explanation:"Black defends e5 and develops. The most natural reply."},{san:"Bc4",explanation:"The Italian bishop. It aims at f7, the weakest square in Black's camp — only the king defends it.",principle:"Target weaknesses"},{san:"Bc5",explanation:"Black's most classical reply, aiming at White's own tender spot on f2. This is the Giuoco Piano."},{san:"c3",explanation:"A pawn move that serves development: it prepares d4, building a big center, and gives the c5 bishop a question to answer later with b4/d4 gains of tempo."},{san:"Nf6",explanation:"Black develops and counterattacks e4. You must deal with this threat."},{san:"d3",explanation:"The 'Pianissimo' — very quiet. Defend e4, keep the center flexible, finish developing, castle. You'll play for d4 (or a kingside attack) at the right moment, not immediately."},{san:"d6",explanation:"Black solidifies e5 the same way. The position is symmetric; the better-prepared player wins the middlegame."},{san:"O-O",explanation:"King safety before move 6. Now the rook is ready to come to e1 supporting the center.",principle:"Castle early"},{san:"a6",explanation:"A modern finesse: Black makes room for the bishop to drop back to a7, out of reach of a future d4 or b4."},{san:"Re1",explanation:"The rook supports e4 so the d2 knight can move freely. A typical 'improve your worst piece' move."},{san:"Ba7",explanation:"The bishop tucks into a7, keeping its diagonal to f2 forever."},{san:"h3",explanation:"A useful prophylactic move: it stops ...Bg4 pinning your knight, and prepares a home on h2 if needed. Now Nbd2-f1-g3 is the classic plan.",principle:"Prophylaxis"}],plans:["Knight tour: Nbd2–f1–g3 (or f1–e3), the signature Italian maneuver, eyeing f5 and d5.","Break with d3-d4 once your pieces are ready, or expand with b4 and a4 on the queenside.","If Black castles kingside, a slow kingside push with Ng3, Nh2-g4 or h3-h4 ideas can create an attack."]},{id:"italian-two-knights",difficulty:1,name:"vs Two Knights: the solid 4.d3",description:"After 3...Nf6 Black invites sharp Fried Liver chaos with 4.Ng5. You sidestep all of it: 4.d3 transposes to the same healthy Pianissimo structure you already know.",side:"white",moves:[{san:"e4",explanation:"Claim the center."},{san:"e5"},{san:"Nf3",explanation:"Develop with tempo against e5."},{san:"Nc6"},{san:"Bc4",explanation:"The Italian bishop, eyeing f7."},{san:"Nf6",explanation:"The Two Knights Defense — Black counterattacks e4 immediately instead of developing the bishop. This invites 4.Ng5, but you don't need that theory."},{san:"d3",explanation:"Calmly defend e4. You give up the sharp 4.Ng5 lines in exchange for a position you understand better than your opponent. Same plans as the main line.",principle:"Play positions you understand"},{san:"Be7",explanation:"Black develops modestly (…Bc5 is also common and transposes to the main line)."},{san:"O-O",explanation:"Castle. Always. Before adventures.",principle:"Castle early"},{san:"O-O"},{san:"Re1",explanation:"Overprotect e4, freeing the b1 knight for its d2–f1–g3 journey."},{san:"d6"},{san:"a4",explanation:"Grabs queenside space and prepares a retreat square on a2 for the bishop (against ...Na5 trade attempts). A key modern move."}],plans:["Same knight tour: Nbd2–f1–g3.","Meet ...Na5 with Ba2 keeping your best piece.","c3 then d4 remains the central break; time it when your pieces are better placed than Black's."]},{id:"italian-evans",difficulty:2,name:"Evans Gambit (attacking weapon)",description:"4.b4!? — sacrifice a pawn to seize the center with tempo. The romantic-era attack that teaches the value of time and initiative. Play this when you want to practice attacking chess.",side:"white",moves:[{san:"e4"},{san:"e5"},{san:"Nf3"},{san:"Nc6"},{san:"Bc4"},{san:"Bc5"},{san:"b4",explanation:"The Evans Gambit. You offer a wing pawn to deflect the bishop and then build the center with gain of time. A pawn buys you two tempi — often a great trade in open positions.",principle:"Time is worth material"},{san:"Bxb4",explanation:"Black accepts (declining with ...Bb6 is safer but concedes the initiative)."},{san:"c3",explanation:"Hit the bishop, gaining a tempo, and prepare d4 — the whole point."},{san:"Ba5",explanation:"The main retreat, keeping the pin option on c3 alive."},{san:"d4",explanation:"The full center arrives with tempo again — d4 attacks e5. Compare: in the Pianissimo this took ten moves of preparation; here the gambit pawn bought it instantly."},{san:"exd4",explanation:"Black must react in the center."},{san:"O-O",explanation:"Ignore the pawns, finish development, connect the rook to the open lines. White's lead in development plus the strong center is worth more than the material.",principle:"Development over material"}],plans:["Regain the pawn with cxd4 or press on with Qb3 hitting f7 and e5-e5 pushes.","Rooks belong on e1 and d1/b1; every open line favors the better-developed side.","If Black grabs a second pawn with ...dxc3, play Qb3! targeting f7 — development beats greed."]}]},{id:"ruy-lopez",name:"Ruy Lopez",eco:"C60–C99",side:"white",order:2,tagline:"The Spanish torture — 500 years old and still the main event",summary:"After 1.e4 e5 2.Nf3 Nc6, the move 3.Bb5 attacks the knight that defends e5 and begins the deepest opening in chess. The modern d3 systems let you play it on understanding rather than memory: slow pressure, endless maneuvering, and the famous 'Spanish bind' that has tortured Black for centuries.",whyPlayIt:["It's the natural graduation from the Italian — same first two moves, one square further for the bishop, ten times the pressure.","The d3 setups sidestep the Marshall Gambit and 30 moves of forced theory while keeping every strategic idea.","Every world champion has played it. The pawn structures you learn here are the vocabulary of top-level chess."],keyPrinciples:["Bb5 pressures e5 indirectly — the threat to take on c6 is rarely real at first, but Black must always reckon with it.","The bishop retreats via a4 to b3 or c2, where it aims at f7/h7 for the whole game.","Re1, c3, and h3 before d4: prepare the center, don't rush it.","The knight tour Nbd2–f1–g3 (borrowed by the Italian) was born here."],commonMistakes:[{mistake:"Taking on c6 without a concrete reason",why:"Bxc6 gives up the Spanish bishop — the piece the whole opening is built around. Trade it only when you win e5 cleanly or double Black's pawns for a real endgame edge (the Exchange Variation plan)."},{mistake:"Allowing ...b5 and ...Na5 to trap the bishop ideas",why:"After ...b5 Bb3, watch for ...Na5 hunting your bishop: c2 must stay available (don't block it with a careless Nc3), or meet ...Na5 with the standard Bc2 retreat."},{mistake:"Pushing d4 before castling and c3",why:"An unprepared d4 lets Black trade into easy equality with ...exd4. The Spanish edge comes from making Black defend e5 forever, not from opening the center early."}],lines:[{id:"ruy-main-d3",difficulty:2,name:"Closed Ruy with d3 (Main Line)",description:"The modern professional treatment: skip the Marshall theory with an early d3, castle, and start the long squeeze. This is the position Carlsen and Caruana have contested dozens of times.",side:"white",moves:[{san:"e4",explanation:"The center, as always.",principle:"Control the center"},{san:"e5"},{san:"Nf3",explanation:"Develop with a threat against e5.",principle:"Develop with threats"},{san:"Nc6"},{san:"Bb5",explanation:"The Spanish move: attack the defender of e5. Unlike the Italian's Bc4, this bishop pressures Black's center indirectly — and Black must spend moves dealing with it forever."},{san:"a6",explanation:"The Morphy Defense — Black immediately asks your bishop its intentions. Played in the overwhelming majority of games."},{san:"Ba4",explanation:"Keep the pressure. Bxc6 is playable (the Exchange), but the bishop is worth more than the structural damage — retreat and keep both advantages in reserve."},{san:"Nf6",explanation:"Black develops and attacks e4, exactly as in the Italian."},{san:"O-O",explanation:"The famous 'free' castle: e4 looks hanging, but 5...Nxe4 runs into Re1 with a well-known pawn recovery — you don't need the details, just castle and trust the theory verdict: safe.",principle:"Castle early"},{san:"Be7",explanation:"Black declines the pawn grab and develops sensibly."},{san:"d3",explanation:"The modern move: defend e4 and refuse Black the Marshall Gambit (...d5 sacrifices need White's d2-d4 setup to bite). Slower, sounder, and rich in ideas rather than memory."},{san:"b5",explanation:"Black gains space and finally forces the bishop off the a4-e8 diagonal."},{san:"Bb3",explanation:"The bishop lands on its dream diagonal, staring at f7. From here it may later slide to c2, joining a kingside attack."},{san:"d6",explanation:"Black solidifies e5 and prepares to castle."},{san:"a4",explanation:"Poke the queenside immediately: the b5 pawn must make a decision, and the a1 rook joins the game without moving twice.",principle:"Create questions"},{san:"Bb7",explanation:"Black develops the bishop to the long diagonal, adding a defender to the fight for d5 and e4."},{san:"Re1",explanation:"Complete the standard Spanish setup: rook behind e4, knight ready for the d2–f1–g3 tour, c3 and h3 to follow. The squeeze begins."}],plans:["The eternal tour: Nbd2–f1–g3 (or f1–e3), then h3, and only then d4 — the center break from full strength.","Meet ...Na5 with Bc2; meet ...b4 with a5, fixing the queenside pawns as targets.","The Spanish endgame rule: trades favor you when Black's queenside pawns are loose — keep a4/axb5 timing in your pocket."]},{id:"ruy-exchange",difficulty:2,name:"Exchange Variation",description:"4.Bxc6: trade the great bishop to wreck Black's pawns, then head for any endgame — where the extra kingside pawn majority wins games on autopilot. Fischer's pet weapon.",side:"white",moves:[{san:"e4"},{san:"e5"},{san:"Nf3"},{san:"Nc6"},{san:"Bb5"},{san:"a6"},{san:"Bxc6",explanation:"The Exchange: give up the bishop pair to inflict doubled pawns. The deal: Black's queenside majority (c6+c7 doubled) can never create a passed pawn, while your healthy kingside majority can. Every endgame is slightly yours."},{san:"dxc6",explanation:"Black recaptures toward the center and opens the c8 bishop — the right way (bxc6? keeps the bad structure with no compensation)."},{san:"O-O",explanation:"Castle and pose the question: e5 is attacked, and defending it costs Black concessions. Note 5.Nxe5? immediately fails to ...Qd4 forking — a classic trap to know from both sides.",principle:"Castle early"},{san:"f6",explanation:"The main defense: solid but slightly ugly, blunting your knight's f3–e5 dreams while weakening the king's diagonal."},{san:"d4",explanation:"Strike now — with the e5 pawn pinned to its defense, trades favor your structure. The center opens on your terms."},{san:"exd4",explanation:"Black must take or lose the center entirely."},{san:"Nxd4",explanation:"Recapture with the knight, centralizing. Threatens to plant on f5 later; more importantly, queens may come off next — exactly what your structure wants."},{san:"c5",explanation:"Black kicks the knight and unravels the doubled pawns' front member."},{san:"Nb3",explanation:"Sidestep, eyeing the c5 pawn and keeping d1 clear. Trade queens whenever offered."},{san:"Qxd1",explanation:"Black usually trades — declining leaves the queen exposed on the open file."},{san:"Rxd1",explanation:"The Fischer endgame: material equal, but count the pawn majorities. Yours (kingside, 4v3) makes a passed pawn by walking; Black's (queenside, 4v3 with doubled c-pawns) never does. Play f4-e5 and march.",principle:"Structure decides endgames"}],plans:["Advance the kingside majority: f4, e5, kingside king. That passed pawn is the whole strategy.","Develop the c1 bishop actively (Be3 hitting c5, or Bf4), rooks to d1/e1.","Avoid piece trades that activate Black's bishops; force pawn-structure endgames instead."]},{id:"ruy-berlin-d3",difficulty:2,name:"vs Berlin: the anti-endgame 4.d3",description:"3...Nf6 invites the infamous Berlin endgame. You refuse: 4.d3 keeps queens on, transposes into familiar Spanish maneuvering, and lets you just play chess.",side:"white",moves:[{san:"e4"},{san:"e5"},{san:"Nf3"},{san:"Nc6"},{san:"Bb5"},{san:"Nf6",explanation:"The Berlin Defense — made famous by Kramnik dethroning Kasparov. Black offers the notorious queenless 'Berlin Wall' endgame after 4.O-O Nxe4. You have a cleaner path."},{san:"d3",explanation:"The anti-Berlin: simply defend e4. No endgame, no wall — just a normal Spanish middlegame where your extra experience with the structure counts.",principle:"Play positions you understand"},{san:"Bc5",explanation:"Black's most active setup, taking the a7-g1 diagonal before ...d6 would block it."},{san:"c3",explanation:"Two jobs: prepare d4 gaining a tempo on the c5 bishop someday, and give your own bishop the c2 retreat. The standard Spanish slow build."},{san:"O-O"},{san:"O-O",explanation:"Both kings safe by move 5 — now the maneuvering battle begins, and that's Spanish home turf.",principle:"Castle early"},{san:"d6",explanation:"Black shores up e5 and unblocks the c8 bishop."},{san:"Nbd2",explanation:"The tour begins: this knight is headed for f1 and then g3 or e3, the maneuver that defines the whole opening family."},{san:"a6",explanation:"The usual question to the bishop."},{san:"Ba4",explanation:"Keep it. From a4 it can drop to c2 behind the pawn chain, joining a future kingside push with b1-h7 pressure."},{san:"Ba7",explanation:"Black tucks the bishop away from d4 tempo-gains, mirroring your Italian knowledge — these systems are cousins."},{san:"h3",explanation:"The last preparatory move: no ...Bg4 pins, luft for the king, and g4-square control for the coming Nf1–g3 knight. Now d4 or Re1 next, position full of play.",principle:"Prophylaxis"}],plans:["Nf1–g3, Re1, then choose: central d4 break or the slow kingside build with Nh2-g4/Qf3 ideas.","The c2-retreat + d4 battery is the main attacking dream — bishop and queen on the b1-h7 diagonal.","If Black ever plays ...d5, meet it with exd5 and pile on e5 — the resulting IQP-ish positions favor your better-placed pieces."]}]},{id:"scotch",name:"Scotch Game",eco:"C44–C45",side:"white",order:3,tagline:"Open the center on move 3 and make Black solve problems immediately",summary:"1.e4 e5 2.Nf3 Nc6 3.d4 — no slow build, no waiting: White trades off the center at once and gets free, active piece play. Kasparov revived it at the world-championship level as a surprise weapon; for learners it teaches open-position skills faster than anything else.",whyPlayIt:["A perfect second weapon beside the Italian/Ruy: same first moves, totally different game — you choose the flavor each night.","Open positions punish slow moves fast, so your tactics training pays immediate rent.","Far less theory than the Ruy Lopez for a comparable initiative."],keyPrinciples:["3.d4 trades a wing-ish pawn stake for instant open lines — development speed is everything after it.","The d4 knight is strong but not sacred: recapture structures (Nxc6 bxc6) often favor you.","Central pawns that advance (e4-e5) gain space with tempo on the f6 knight.","Queens on f6/g6 are Black's standard tries — meet aggression with development, not pawn grabs."],commonMistakes:[{mistake:"Defending the d4 knight with awkward pieces when attacked",why:"After ...Bc5 and ...Qf6 pile on d4, moves like Nf3? retreat concede the whole point. The book answers (Be3, c3, Nb3) keep developing while defending — learn them as a package."},{mistake:"Letting the e5 push evaporate without gain",why:"In Mieses lines the e5 pawn cramps Black's knight — trading it off carelessly (exf6?) repairs Black's structure. Push it, support it, and make Black pay moves to challenge it."},{mistake:"Ignoring the g2 pawn once Black's queen reaches g6",why:"...Qg6 hits both e4 and g2. Castling covers g2; unprepared moves lose material to a two-target fork you saw coming."}],lines:[{id:"scotch-classical",difficulty:2,name:"Classical (4...Bc5 main line)",description:"Black develops the bishop to its most natural square and attacks your d4 knight. You'll learn the Be3/c3 defensive-developing package and come out ahead in activity.",side:"white",moves:[{san:"e4"},{san:"e5"},{san:"Nf3"},{san:"Nc6"},{san:"d4",explanation:"The Scotch: strike the center NOW. Black can't maintain e5 — the position opens while your development leads.",principle:"Open lines when ahead in development"},{san:"exd4",explanation:"Practically forced; defending e5 with 3...d6 concedes the center after 4.dxe5."},{san:"Nxd4",explanation:"Recapture with the knight — centralized, flexible, and the c-pawn stays free for c3 support later."},{san:"Bc5",explanation:"The Classical: Black develops with a threat, hitting the d4 knight and eyeing f2. The critical test of your setup."},{san:"Be3",explanation:"Defend by developing: the bishop guards d4 and offers a favorable trade — if ...Bxd4 Bxd4, your bishop dominates the long diagonal.",principle:"Defend with developing moves"},{san:"Qf6",explanation:"Black piles on d4 a second time and threatens mate-adjacent ideas on f2. Aggressive — and exactly what the next move calmly handles."},{san:"c3",explanation:"The key move of the whole line: the d4 knight is now defended by pawn, bishop stays on e3, and b4/d4 tempo-gains hang over Black's bishop. Black's early aggression starts costing time."},{san:"Nge7",explanation:"Black develops the last knight toward d5/f5 — g6 ideas for the queen need this square vacated."},{san:"Bc4",explanation:"Develop with an eye on f7. (The main move 6.g3 exists too; Bc4 is the classical human choice.)"},{san:"Ne5",explanation:"Black centralizes with tempo on your bishop — the point of the e7 knight's flexibility."},{san:"Be2",explanation:"Calm retreat. Black's knights look impressive but have moved three times; your whole army is developing. Time will tell — in your favor.",principle:"Time is worth material"},{san:"Qg6",explanation:"The consistent follow-up: the queen hits e4 and g2 simultaneously. One precise move defuses both."},{san:"O-O",explanation:"Castle: g2 is covered by the king's rook-file structure (…Qxe4?? drops the queen to Re1 pins/skewers ideas — the e-file is yours), and your last pieces flow out. Black's initiative is spent; your structure and lead remain.",principle:"Castle early"}],plans:["Nd2 (protecting e4 again) then Re1 — the e-file pressure makes ...Qxe4 permanently poisoned.","Advance f4 hitting the e5 knight at the right moment; Black's pieces get pushed backward.","Trade dark-squared bishops via Bg5 or d4-ideas later; Black's remaining pieces coordinate poorly."]},{id:"scotch-mieses",difficulty:3,name:"Mieses (4...Nf6 5.Nxc6)",description:"Kasparov's line: meet the knight attack on e4 with a structure-damaging trade and the cramping e5 push. Sharp, modern, and full of energy.",side:"white",moves:[{san:"e4"},{san:"e5"},{san:"Nf3"},{san:"Nc6"},{san:"d4"},{san:"exd4"},{san:"Nxd4"},{san:"Nf6",explanation:"Black counterattacks e4 instead of developing the bishop — the sharpest reply, inviting complications."},{san:"Nxc6",explanation:"The Mieses move: damage the structure first. Now Black's b-pawns double and e4 gets dealt with next move by advancing, not defending."},{san:"bxc6",explanation:"Black accepts doubled pawns for the open b-file and a big pawn center — a genuine trade of imbalances."},{san:"e5",explanation:"The point: push with tempo. The f6 knight must move again, and the pawn cramps Black's kingside for the rest of the opening.",principle:"Gain space with tempo"},{san:"Qe7",explanation:"Black pins the e-pawn to your king — the main move, awkward-looking but forcing you to be precise."},{san:"Qe2",explanation:"Mirror the pin problem away: protect e5 and prepare to unwind with development. Queens face off through the pawn; neither can profitably take."},{san:"Nd5",explanation:"The knight finds its permanent home, hitting c7-adjacent squares and blockading beautifully. Black's best piece — your next moves undermine it."},{san:"c4",explanation:"Kick immediately. The knight must choose a worse square or trade its glory."},{san:"Ba6",explanation:"The modern main move: pin the c4 pawn against your queen, keeping the d5 knight afloat. Sharpest theory — and one natural move keeps you fine."},{san:"b3",explanation:"Break the pin by defending c4 with a pawn. Your bishop comes to b2 next with a monster diagonal once the e5 pawn advances or trades — the Mieses tabiya, roughly balanced and rich in play for both sides.",principle:"Solve problems with structure"}],plans:["Develop Bb2 and g3/Bg2 (the double-fianchetto scheme) — both long diagonals point at Black's king zones.","The e5 pawn is your space rent: support it with f4 when challenged by ...f6.","Endgames favor you: Black's doubled c-pawns are the lasting scar; trade actively toward them."]}]},{id:"queens-gambit",name:"Queen's Gambit",eco:"D06–D69",side:"white",order:4,tagline:"The most respected 1.d4 opening — pressure that lasts all game",summary:"1.d4 d5 2.c4 offers a pawn Black can rarely keep, in exchange for a lasting grip on the center. The Queen's Gambit teaches pawn-structure chess: minority attacks, isolated pawns, and long-term pressure instead of quick tricks.",whyPlayIt:["It's not really a gambit — if Black takes on c4, White regains the pawn with a better center almost by force.","The structures you learn (Carlsbad, isolated queen's pawn, hanging pawns) reappear in dozens of other openings.","It rewards understanding over memorization; plans matter more than move orders."],keyPrinciples:["c4 pressures d5 — the fight is for the central light squares.","Develop the queen's bishop actively (Bg5 or Bf4) before locking it in with e3.","Recapture toward the center; keep your pawn structure healthy.","Against ...dxc4, don't rush — regain the pawn with tempo (Bxc4) when it helps development."],commonMistakes:[{mistake:"Playing e3 before developing the c1 bishop",why:"e3 entombs your queen's bishop behind its own pawns. Bg5 (or Bf4) first, e3 second — the difference between a good and a passive Queen's Gambit."},{mistake:"Chasing the c4 pawn immediately after 2...dxc4",why:"Moves like 3.Qa4+ regain the pawn but misplace the queen. 3.e3 or 3.Nf3 develops first; the pawn cannot be held (…b5 is met by a4! undermining)."},{mistake:"Allowing ...Bb4 pins to wreck your queenside without a plan",why:"Know your answer in advance: a3 to ask the question, or Bd2 to break the pin. Unprepared, the doubled c-pawns become a long-term weakness."}],lines:[{id:"qg-qgd-main",difficulty:2,name:"QGD Main Line (Bg5 Orthodox)",description:"The classical tabiya: both sides develop to their best squares, and you learn Capablanca's famous freeing maneuver from the Black side while playing the White side of it.",side:"white",moves:[{san:"d4",explanation:"Occupy the center. Unlike 1.e4, the d4 pawn is defended by the queen from the start, so this leads to slower, more strategic play.",principle:"Control the center"},{san:"d5",explanation:"Black stakes an equal claim."},{san:"c4",explanation:"The Queen's Gambit: attack d5 with a flank pawn. If Black captures, White gets a strong center; if Black defends, the c4 pawn keeps pressuring d5 forever."},{san:"e6",explanation:"The Declined — Black solidly defends d5, accepting a slightly passive light-squared bishop as the price."},{san:"Nc3",explanation:"Develop and add a third attacker to d5."},{san:"Nf6",explanation:"Black defends d5 a second time and develops."},{san:"Bg5",explanation:"The key move: develop the bishop OUTSIDE the pawn chain before playing e3. The pin on f6 indirectly pressures d5 — the knight is the defender.",principle:"Bishops before e3"},{san:"Be7",explanation:"Black breaks the pin calmly."},{san:"e3",explanation:"Now e3 is fine — the bishop is already out. Solidify d4, open the f1 bishop's diagonal."},{san:"O-O",explanation:"Black castles.",principle:"Castle early"},{san:"Nf3",explanation:"Natural development toward the center. White will castle next."},{san:"Nbd7",explanation:"Black's knight supports ...c5 and ...e5 breaks and its brother on f6."},{san:"Rc1",explanation:"A quiet but deep move: the rook goes to the file that will open when pawns trade on d5/c5. Prophylaxis against Black's freeing ...c5.",principle:"Rooks to open files"},{san:"c6",explanation:"Black shores up d5 and prepares the classic freeing plan: ...dxc4 followed by ...Nd5."},{san:"Bd3",explanation:"Finish development, preparing to castle. Note White delayed this so that ...dxc4 wouldn't hit the bishop earlier — small move-order finesses matter here."},{san:"dxc4",explanation:"Capablanca's freeing idea begins: Black trades the cramped position's tension away…"},{san:"Bxc4",explanation:"White recaptures with tempo-neutral development. The bishop is well placed on c4."},{san:"Nd5",explanation:"…and offers piece trades with this centralizing jump. Cramped positions want trades; White should keep pieces on."},{san:"Bxe7",explanation:"Trading the dark-squared bishops is fine — White keeps the better minor pieces and more space. Avoid Bh4? which loses the bishop pair after ...Nxc3."},{san:"Qxe7",explanation:"The tabiya of the Orthodox QGD. White is a shade better: more space, freer bishop, clearer plans."}],plans:["Play e4 in one go if Black allows it (after Nxc3 bxc3, the center pawn duo advances).","Rooks to c1/d1, then press the c-file and the queenside minority attack (b4-b5).","Trade light-squared bishops via Bd3/e2–a6 ideas when it wins the c-file battle."]},{id:"qg-qga",difficulty:1,name:"vs Queen's Gambit Accepted: 3.e3",description:"When Black takes the pawn, you calmly regain it with a comfortable, active position. The lesson: the c4 pawn was never really a sacrifice.",side:"white",moves:[{san:"d4"},{san:"d5"},{san:"c4"},{san:"dxc4",explanation:"Black accepts. The plan is to give the pawn back at the right moment and free the position with ...c5 — but White gets easy development meanwhile."},{san:"e3",explanation:"Simple and strong: open the bishop's path to c4 to regain the pawn. (3.Nf3 first is equally good and avoids ...e5 ideas.)"},{san:"Nf6",explanation:"Black develops; trying to keep the pawn with 3...b5? fails to 4.a4! when the queenside collapses."},{san:"Bxc4",explanation:"Pawn regained, bishop developed — two jobs, one move.",principle:"Develop with purpose"},{san:"e6",explanation:"Black opens the f8 bishop and prepares ...c5."},{san:"Nf3",explanation:"Develop toward the center, control e5."},{san:"c5",explanation:"The thematic strike at White's center — Black must challenge d4 or get squeezed."},{san:"O-O",explanation:"King safety first; keep the central tension.",principle:"Castle early"},{san:"a6",explanation:"Black prepares ...b5 gaining space and a tempo on the bishop."},{san:"Qe2",explanation:"A key idea: the queen steps to e2 so the f1 rook can come to d1 opposite Black's queen, and supports a future e3-e4 advance."},{san:"b5",explanation:"Black expands with tempo."},{san:"Bb3",explanation:"The bishop keeps its strong diagonal toward e6/f7. Next comes Rd1 and the central push e4 — White's whole setup aims at it."}],plans:["Rd1, Nc3, then the central break e3-e4 — White's space advantage becomes an attack.","If Black trades ...cxd4, recapture and use the isolated d-pawn actively: it cramps Black and supports Ne5.","Watch the c4-square: after ...b5, a4! often undermines Black's queenside expansion."]},{id:"qg-slav",difficulty:2,name:"vs Slav: Main Line with a4",description:"Against 2...c6 — the Slav, defending d5 without blocking the bishop — you learn the main line where White trades a small queenside concession (a4) for the strong central duo e4+d4.",side:"white",moves:[{san:"d4"},{san:"d5"},{san:"c4"},{san:"c6",explanation:"The Slav: Black defends d5 with a pawn while keeping the c8 bishop's diagonal open — fixing the QGD's one drawback."},{san:"Nf3",explanation:"Flexible development; White waits to see Black's setup before committing the b1 knight."},{san:"Nf6"},{san:"Nc3",explanation:"Now pressure d5 properly."},{san:"dxc4",explanation:"The main line: Black grabs the pawn, planning to hold it just long enough to make White spend time."},{san:"a4",explanation:"The point: prevent ...b5 which would protect c4. White will regain the pawn, but a4 slightly weakens b4 — the Slav's fair trade."},{san:"Bf5",explanation:"Black develops the bishop actively before ...e6 — the entire point of the Slav move order."},{san:"e3",explanation:"Prepare to take on c4 with the bishop."},{san:"e6",explanation:"Black completes the pawn shell."},{san:"Bxc4",explanation:"Pawn regained with development, as always."},{san:"Bb4",explanation:"Black pins, fighting for the e4-square — if the c3 knight is pinned, e3-e4 is harder to achieve."},{san:"O-O",explanation:"Castle and break the pin's sting — now Nxe4 tricks fail because there's no pin on the king.",principle:"Castle early"},{san:"O-O"},{san:"Qe2",explanation:"The main move: prepare e3-e4 anyway. The central majority is White's trump; everything serves that break."}],plans:["Achieve e3-e4: after e4, Bg6, the center may advance further with e5 gaining space.","The b4-square (weakened by a4) is Black's; don't let a knight sit there unchallenged — Na2 or Bd2 trades help.","Endgames favor White's central majority; trade into them from strength."]}]},{id:"london",name:"London System",eco:"D02, A46",side:"white",order:5,tagline:"One solid setup against nearly everything Black plays",summary:"1.d4 and 2.Bf4: White builds the same healthy pyramid (d4, e3, c3) with the bishop developed OUTSIDE the chain, against almost any Black defense. Minimal memorization, maximum structure — and real attacking plans with Ne5 and a kingside push.",whyPlayIt:["One setup covers 90% of Black replies — your study time goes to plans, not move orders.","The bishop on f4 is the London's soul: active outside the pawn chain before e3 seals it.","Quietly aggressive: the Ne5 + f4 or Bd3+Ne5 battery generates genuine kingside attacks."],keyPrinciples:["Build the pyramid: pawns on d4-e3-c3, bishop out to f4 first.","The e5-square is your outpost — knights dream of landing there.","Keep the f4 bishop safe: h3 gives it a retreat on h2 when attacked by ...Bd6 or ...Nh5.","Play the position, not the clock — the London wins in the middlegame, not the opening."],commonMistakes:[{mistake:"Autopiloting the setup regardless of what Black does",why:"The London is a system, not a script. Against an early ...c5 you need c3 promptly; against kingside fianchettos the plans change entirely. Watch the board."},{mistake:"Letting ...Qb6 hit b2 unanswered",why:"The classic London sting: with the c1 bishop on f4, b2 hangs. Know the answers: Qb3 offering the trade, or Rb1/b3 setups. Never just lose the pawn."},{mistake:"Trading the f4 bishop for a knight casually",why:"The dark-squared bishop is the system's best piece. Retreat it (Bg3, Bh2) rather than swap it for a random knight."}],lines:[{id:"london-main",difficulty:1,name:"Main Line vs ...d5",description:"The classical London structure against a symmetric setup. Learn the pyramid, the Nbd2+Ngf3 development scheme, and the signature Ne5 outpost.",side:"white",moves:[{san:"d4",explanation:"Central control, long-game style.",principle:"Control the center"},{san:"d5"},{san:"Bf4",explanation:"The London move: bishop OUT before the pawn chain closes with e3. Compare the QGD where this bishop can get stuck on c1.",principle:"Bishops before e3"},{san:"Nf6"},{san:"e3",explanation:"Now the chain closes behind the bishop. Solid, and the f1 bishop's diagonal opens."},{san:"c5",explanation:"Black strikes at d4 immediately — the most testing plan."},{san:"c3",explanation:"Reinforce d4 and complete the pyramid. The center will not be shaken."},{san:"Nc6"},{san:"Nd2",explanation:"Knight development the London way: b1 goes to d2 first (supporting a later Ne5 recapture and keeping f3 free), then g1 to f3."},{san:"e6",explanation:"Black opens the f8 bishop."},{san:"Ngf3",explanation:"The scheme completes. Both knights support the e5-square — the London's promised land."},{san:"Bd6",explanation:"Black challenges the London bishop — the critical test. Trading on f4 would strengthen White's structure, so White retreats."},{san:"Bg3",explanation:"Keep the bishop! If Black ever takes on g3, hxg3 opens the h-file for the rook — a hidden attacking resource. The bishop also keeps supporting e5.",principle:"Preserve your best pieces"},{san:"O-O"},{san:"Bd3",explanation:"The attacking diagonal b1-h7, aimed at Black's castled king."},{san:"b6",explanation:"Black develops the bishop to b7."},{san:"Ne5",explanation:"The signature move: the knight lands on the outpost, supported by d4 (and after ...Bxe5 dxe5, the pawn kicks the f6 knight and White's attack plays itself)."}],plans:["The dream attack: Ne5, f4 (after the g3 bishop is settled), Qf3-h3, and a kingside pawn storm.","If Black trades ...Bxe5 dxe5, the f6 knight is kicked, and White's e5 pawn cramps the kingside — attack with Qg4/h4-h5.","Queenside tension (cxd4/dxc5) usually favors whoever is better developed — often you."]},{id:"london-kid",difficulty:2,name:"vs King's Indian setup (...g6)",description:"When Black fianchettos, the London adapts: h3 preserves the bishop, c3 blunts the g7 bishop, and White plays for the e4 break or a queenside expansion.",side:"white",moves:[{san:"d4"},{san:"Nf6"},{san:"Bf4",explanation:"Same second move against nearly everything — that's the London promise."},{san:"g6",explanation:"Black goes King's Indian style: the g7 bishop will pressure d4 from afar."},{san:"e3"},{san:"Bg7"},{san:"Nf3"},{san:"O-O"},{san:"h3",explanation:"A key prophylactic move in this line: it guarantees the f4 bishop a safe home on h2 when Black plays ...Nh5 or ...e5-e4 tricks, and stops ...Ng4.",principle:"Prophylaxis"},{san:"d6",explanation:"Black prepares the thematic ...e5 break — the whole point of the King's Indian setup."},{san:"Be2",explanation:"Modest but right: on e2 the bishop stays out of ...e5-e4 forks and supports a later kingside defense. White will castle and meet ...e5 calmly."},{san:"Nbd7",explanation:"Black masses for ...e5."},{san:"O-O",explanation:"Castle before the center opens.",principle:"Castle early"},{san:"Qe8",explanation:"A typical King's Indian regrouping: the queen supports ...e5 (and dreams of ...e4 and kingside expansion with ...f5)."},{san:"c3",explanation:"Blunt the g7 bishop's diagonal in advance. When ...e5 comes, White simply keeps the structure with dxe5 or Bh2 and stands solid."},{san:"e5",explanation:"The break arrives."},{san:"Bh2",explanation:"The prepared retreat — the bishop stays on the b8-h2 diagonal, e5 remains under tension, and White has a comfortable game with more space on the queenside next (b4, a4)."}],plans:["Queenside space: b4, a4, and c4-c5 gaining ground while Black attacks air on the kingside.","Keep the tension on e5; dxe5 at the moment it wins a tempo or opens lines your rooks own.","If Black overextends with ...f5-f4, hit back in the center with exf4/c4 — the g7 bishop stays buried."]}]},{id:"caro-kann",name:"Caro-Kann Defense",eco:"B10–B19",side:"black",order:6,tagline:"Your answer to 1.e4 — solid structure, no bad bishop",summary:"1.e4 c6 prepares ...d5, challenging the center while keeping the c8 bishop's diagonal open — solving the French Defense's biggest problem. The Caro-Kann gives Black one of the healthiest pawn structures in chess and clear, learnable plans in every White variation.",whyPlayIt:["Rock-solid: Black's structure has no permanent weaknesses, so small mistakes don't lose games.","The light-squared bishop develops OUTSIDE the pawn chain before ...e6 — the defining advantage over the French.","White's three main tries (Advance, Exchange, Classical) each have one clear Black recipe — perfect for building a real repertoire."],keyPrinciples:["...c6 and ...d5 challenge e4 with pawns, not pieces — structure first.","Develop the c8 bishop (to f5 or g4) BEFORE playing ...e6.","The ...c5 break is your source of counterplay in blocked positions.","Trade pieces when cramped; keep the healthy endgame structure in mind — many Caro endgames favor Black."],commonMistakes:[{mistake:"Playing ...e6 before developing the c8 bishop",why:"That one move-order slip turns your Caro-Kann into a bad French. The bishop goes to f5 (or g4) first — it's the entire point of 1...c6."},{mistake:"Grabbing the b2 pawn with the queen in the Exchange lines",why:"...Qb6xb2 walks into development traps. The Caro-Kann's promise is solidity; cash it in with sound moves, not pawn grabs."},{mistake:"Never playing the ...c5 break",why:"Passive shuffling lets White attack for free, especially in the Advance. ...c5 is your rent payment on the position — plan it from move 5."}],lines:[{id:"caro-advance",difficulty:1,name:"vs Advance Variation (3.e5 Bf5)",description:"White grabs space with 3.e5; you instantly develop the bishop to its dream square, then chip at the chain with ...c5. The short-system main line every Caro player must know.",side:"black",moves:[{san:"e4"},{san:"c6",explanation:"The Caro-Kann. A quiet pawn move preparing ...d5 — challenging the center next move with full pawn support.",principle:"Prepare pawn breaks"},{san:"d4",explanation:"White builds the big center."},{san:"d5",explanation:"The challenge: e4 must advance, trade, or be defended."},{san:"e5",explanation:"The Advance Variation: White gains space and fixes the center. The pawn chain points kingside — that's where White will play. Your counterplay targets its base: d4."},{san:"Bf5",explanation:"THE move to remember: the bishop escapes before ...e6 closes the door. On f5 it's active and eyes b1-h7. This is why you chose the Caro over the French.",principle:"Bishop outside the chain"},{san:"Nf3",explanation:"White develops sensibly (the aggressive 4.Nc3/4.h4 lines exist, but this is the modern main try)."},{san:"e6",explanation:"NOW ...e6 is fine — the bishop is out. The structure is complete and unbreakable."},{san:"Be2",explanation:"The Short System: quiet development, planning O-O, c3, and slow kingside expansion."},{san:"c5",explanation:"The thematic break, hitting the chain's base at d4. Note c6 spent one tempo, then c5 another — acceptable, because White's e5 space means nothing if the center dissolves.",principle:"Attack the chain's base"},{san:"Be3",explanation:"White defends d4 and keeps the tension."},{san:"cxd4",explanation:"Trade at YOUR moment. This clarifies the center before developing the knights."},{san:"Nxd4",explanation:"White recaptures with the knight, eyeing f5."},{san:"Ne7",explanation:"Flexible: this knight covers f5 against Nxf5 tricks and can reroute to c6 or g6. Develop the g8 knight via e7 in the Advance — ...Nf6 would bite on e5's granite."},{san:"O-O"},{san:"Nbc6",explanation:"Challenge the strong d4 knight; if White trades, Black's pieces free up and the e5 pawn needs babysitting forever."}],plans:["Trade on d4 and pressure e5 with ...Nc6/...Qb6 — White's proud chain becomes a liability.","...Ng6 or ...h5-h4 gains kingside space; the f5 bishop can drop to g6 keeping the wall.","Endgames are your friend: the space advantage evaporates, the healthy structure remains."]},{id:"caro-exchange",difficulty:2,name:"vs Exchange Variation (3.exd5 cxd5)",description:"White trades on d5 hoping for a quiet game; you get free development and a clear plan. Includes the key ...Na5! resource against the Qb3 pressure setup.",side:"black",moves:[{san:"e4"},{san:"c6"},{san:"d4"},{san:"d5"},{san:"exd5",explanation:"The Exchange: White avoids theory, aiming for a symmetric-ish structure with a tiny edge. Don't relax — play precisely and YOU get the better version."},{san:"cxd5",explanation:"Recapture toward the center. The half-open c-file is now yours; a rook belongs there eventually.",principle:"Recapture toward the center"},{san:"Bd3",explanation:"The critical try: White grabs the b1-h7 diagonal before Black's bishop can contest it."},{san:"Nc6",explanation:"Develop with pressure on d4. The knight also prepares the key defensive resource coming up."},{san:"c3",explanation:"White solidifies d4 and opens the queen's path to b3 — the point of the whole setup: pressure on b7 and d5."},{san:"Nf6"},{san:"Bf4",explanation:"White develops actively, London-style. Now comes the critical moment."},{san:"Bg4",explanation:"Develop the bishop actively with tempo on... nothing yet — but it provokes exactly what follows. You must know the next few moves."},{san:"Qb3",explanation:"The sting: b7 and d5 are both attacked. Panic loses a pawn; the book move holds everything."},{san:"Na5",explanation:"The resource! Counterattack the queen. b7 is poisoned anyway in many lines, and after the forced sequence the knight returns with gain of time.",principle:"Meet threats with counterthreats"},{san:"Qa4+",explanation:"Forced sidestep with check."},{san:"Bd7",explanation:"The g4 bishop retreats to block — annoying-looking, but the queen must move again, and Black regains all the time."},{san:"Qc2",explanation:"The queen settles. Count the tempi: White's queen moved three times. Black is fully equal — develop, castle, take the c-file."}],plans:["...e6, ...Bd6 (challenging f4), ...O-O, then rooks to c8 — the half-open c-file is the game's main road.","The minority attack in reverse: ...b5-b4 gaining space and creating a weak c3 pawn.","Re-route the a5 knight via c4 or c6; on c4 it dominates."]},{id:"caro-classical",difficulty:2,name:"vs Classical (3.Nc3 dxe4 4.Nxe4 Bf5)",description:"The old main line: you trade in the center, develop the bishop with tempo, and follow the famous h-pawn dance to a position Capablanca would happily defend.",side:"black",moves:[{san:"e4"},{san:"c6"},{san:"d4"},{san:"d5"},{san:"Nc3",explanation:"The Classical: White defends e4 with pieces and keeps the tension."},{san:"dxe4",explanation:"Take! Black wins the structural battle: White's d4 will forever be a target while Black has no weaknesses at all."},{san:"Nxe4"},{san:"Bf5",explanation:"Develop with tempo — the bishop attacks the e4 knight. The defining Caro-Kann picture again: bishop out, then ...e6.",principle:"Develop with threats"},{san:"Ng3",explanation:"The knight retreats, hitting the bishop back."},{san:"Bg6",explanation:"The bishop slides to safety, still on its diagonal."},{san:"h4",explanation:"White gains kingside space and threatens h5 trapping the bishop — the famous dance begins. Every move is forced and worth knowing cold."},{san:"h6",explanation:"Make luft for the bishop on h7. Not ...h5? which fixes the pawn as a permanent weakness."},{san:"Nf3"},{san:"Nd7",explanation:"Covers e5 and prepares ...Ngf6 without allowing doubled pawns after a knight trade — a small but classic finesse."},{san:"h5",explanation:"White pushes anyway, forcing the bishop home."},{san:"Bh7",explanation:"Perfectly safe on h7 — it will trade itself for White's good bishop next."},{san:"Bd3",explanation:"White offers the trade to blunt Black's best piece — but the trade costs White time and the h5 pawn stays weak long-term."},{san:"Bxd3",explanation:"Trade happily. Black's remaining pieces all have natural squares, and White's h5 pawn needs a defender in every endgame."},{san:"Qxd3",explanation:"The tabiya: Black is slightly cramped but structurally perfect. ...e6, ...Ngf6, ...Be7, ...O-O follow, with a comfortable, famously resilient game."}],plans:["Complete the wall: ...e6, ...Ngf6, ...Be7, castle short (queenside castling is also a sharp option after ...Qc7).","The ...c5 break (again!) challenges d4 once developed.","In endgames, White's h5 pawn and Black's pristine structure are your long-term interest payments."]}]},{id:"sicilian",name:"Sicilian Defense (Najdorf)",eco:"B90–B99",side:"black",order:7,tagline:"The fighting answer to 1.e4 — play for the win with Black",summary:"1.e4 c5 refuses symmetry: Black trades a wing pawn fight for the half-open c-file and winning chances in every game. The Najdorf move order (…a6) is the most respected version — Fischer's and Kasparov's lifetime weapon. This is your aggressive alternative to the solid Caro-Kann.",whyPlayIt:["The Caro-Kann asks for equality; the Sicilian asks for the full point. Having both makes you dangerous.","The half-open c-file gives Black a ready-made plan in every line: pressure c2 with rooks and the ...Qc7/...Rc8 battery.","The Najdorf's ...a6 is pure usefulness: it stops Bb5+/Nb5 annoyances and prepares ...b5 expansion before committing the center."],keyPrinciples:["…cxd4 trades a flank pawn for a center pawn — Black wins the long-term structural bargain in most endgames.","The d6–e5 (or d6–e6) small center is a spring, not a weakness: it coils, then strikes with ...d5.","Queenside is your side: ...b5, ...Bb7, ...Rc8 come almost regardless of White's setup.","Know your move order cold up to move 6 — the Sicilian punishes autopilot more than any opening."],commonMistakes:[{mistake:"Grabbing the b2 pawn with the queen (the 'Poisoned Pawn') without knowing the theory",why:"…Qb6xb2 is a real variation — for people with 30 moves memorized. Until then, treat b2 as poison: develop instead and keep the position's natural plusses."},{mistake:"Playing ...d5 before it's fully prepared",why:"The freeing break is the Sicilian's dream, but one move early it just opens lines for White's better-developed pieces. Count defenders of d5 first; when in doubt, improve a piece."},{mistake:"Castling into a pawn storm without counterplay running",why:"Against opposite-side castling (English Attack setups), your queenside pawns must already be rolling when White's g4 arrives. Attack speed, not defense, is the Sicilian's shield."}],lines:[{id:"sicilian-najdorf-be2",difficulty:2,name:"Najdorf vs 6.Be2 (Opocensky)",description:"The classical main line: White develops quietly and you get the full Najdorf experience — ...e5, the d5-square bargain, and Black's model piece setup.",side:"black",moves:[{san:"e4"},{san:"c5",explanation:"The Sicilian: fight for d4 with a wing pawn and unbalance the game from move one. No symmetry, no easy draws — chess with the gloves off.",principle:"Fight for the center"},{san:"Nf3"},{san:"d6",explanation:"Control e5 and open the c8 bishop's diagonal, preparing the standard Najdorf skeleton."},{san:"d4",explanation:"The Open Sicilian: White trades the d-pawn for your c-pawn — accepting the structural bargain to get fast development and attacking chances."},{san:"cxd4",explanation:"Take, of course: a center pawn for a wing pawn. Every Sicilian endgame smiles at you because of this trade.",principle:"Trade wing pawns for center pawns"},{san:"Nxd4"},{san:"Nf6",explanation:"Develop with tempo on e4 — forcing White's next move before choosing your setup."},{san:"Nc3"},{san:"a6",explanation:"THE Najdorf move. Quiet but multi-purpose: b5 is denied to White's pieces (no Bb5+, no Nd5-b5 tricks), ...e5 becomes safe from Bb5 pins, and ...b5 expansion is prepared. A tempo spent on pure usefulness."},{san:"Be2",explanation:"The Opocensky: White develops classically and castles short — the calmest main line and the perfect one to learn the Najdorf's ideas against."},{san:"e5",explanation:"The thematic strike: kick the d4 knight and claim the center. Yes, d5 becomes a hole — the Najdorf's eternal bargain: White gets a square, you get space, activity, and the better structure everywhere else.",principle:"Concrete gains over abstract weaknesses"},{san:"Nb3",explanation:"The knight retreats (Nf5? drops it to ...Bxf5 setups after ...g6 preparation — and ...d5 tricks loom)."},{san:"Be7",explanation:"Simple development; the bishop watches g5 against pin ideas."},{san:"O-O"},{san:"O-O",explanation:"Both castled. Now the real Najdorf middlegame: White probes d5, you expand queenside.",principle:"Castle early"},{san:"Be3"},{san:"Be6",explanation:"Mirror development with a purpose: the bishop covers d5 — the hole is only a hole if White's pieces can live there. Your whole setup conspires to make d5 uninhabitable."}],plans:["The full setup: ...Nbd7, ...Qc7, ...Rc8 (or ...b5 first) — queenside pressure on autopilot.","Meet Nd5 jumps with ...Bxd5/...Nxd5 recapture calculations ready; often ...Nxd5 exd5 leaves White's pawn there as a target.","The dream break stays ...d5 in one go when tactics allow — it usually equalizes instantly or better."]},{id:"sicilian-alapin",difficulty:2,name:"vs Alapin (2.c3)",description:"Club players' favorite anti-Sicilian: White wants a big center with d4 next. The antidote is immediate: 2...Nf6 hits e4 before c3's plan connects.",side:"black",moves:[{san:"e4"},{san:"c5"},{san:"c3",explanation:"The Alapin: White prepares d4 with pawn support, dodging Open Sicilian theory. Its cost is written on the board — c3 steals the b1 knight's best square, and your play targets exactly that."},{san:"Nf6",explanation:"The principled answer: attack e4 at once. White must push e5 (the main line) or defend awkwardly — c3 already spent the natural defender's square.",principle:"Punish slow moves with development"},{san:"e5",explanation:"Forward — but now the pawn needs constant care, and your knight finds a beautiful home."},{san:"Nd5",explanation:"Perfectly placed: c3 means no Nc3 to challenge it, so the knight sits centrally, untouchable by pieces, watching f4/e3/c3."},{san:"d4",explanation:"White builds the intended center."},{san:"cxd4",explanation:"Trade at once — every exchange highlights that e5 is overextended rather than strong."},{san:"Nf3",explanation:"White develops before recapturing (cxd4 immediately allows the same setup; move orders blend)."},{san:"Nc6",explanation:"Develop with pressure on both d4 and e5 — White's center must keep answering questions."},{san:"cxd4",explanation:"White restores the pawn duo — momentarily impressive, permanently targetable."},{san:"d6",explanation:"The lever: strike the e5 spearhead. The center White built starts costing tempo to maintain.",principle:"Attack the chain's base"},{san:"Bc4",explanation:"White develops with tempo on your knight — the critical moment; retreating wrongly hands White everything."},{san:"Nb6",explanation:"The book square: hit the bishop back, keep d5 covered, and prepare ...dxe5 under the best terms. Not ...Nf4? losing the knight's stability for nothing."},{san:"Bb5",explanation:"White pins, trying to keep the initiative before the center falls."},{san:"dxe5",explanation:"Take — the point of everything since move 2: White's proud center dissolves into an isolated d-pawn."},{san:"Nxe5",explanation:"White recaptures with the knight, briefly active…"},{san:"Bd7",explanation:"…and one calm developing move breaks the pin, hits the b5 bishop, and leaves you with the healthier structure: White's d4 is isolated, your position has no weaknesses. Classic anti-Alapin success.",principle:"Develop with threats"}],plans:["After trades on d7/c6, blockade d5 with a knight and gang up on the isolated d4 pawn — rooks to d8.","...e6 and ...Be7, castle short; the endgame is your friend (isolated pawn again).","If White avoids trades, expand with ...a6/...e6 and outplay the passive pieces — c3's tempo never comes back."]},{id:"sicilian-english-attack",difficulty:3,name:"Najdorf vs English Attack (6.Be3)",description:"The sharpest test: White castles long and storms your king. You learn the race — ...e5, ...Be6, and queenside pawns that hit first.",side:"black",moves:[{san:"e4"},{san:"c5"},{san:"Nf3"},{san:"d6"},{san:"d4"},{san:"cxd4"},{san:"Nxd4"},{san:"Nf6"},{san:"Nc3"},{san:"a6"},{san:"Be3",explanation:"The English Attack: White intends f3, Qd2, O-O-O, and a g4-h4 pawn storm at your castled king. Terrifying by reputation — beatable by system. Your system starts now."},{san:"e5",explanation:"Same thematic strike as the main line — claim the center immediately, before White's setup congeals. The d5 hole matters less than the tempo war you're about to win.",principle:"Meet wing plans with central play"},{san:"Nb3",explanation:"The retreat, as usual (Nf5 ideas fail to the same preparation as before)."},{san:"Be6",explanation:"Cover d5 instantly — this bishop is the Najdorf's unsung hero. Your minor pieces coordinate to make White's dream knight-on-d5 impossible."},{san:"f3",explanation:"The English Attack signature: overprotect e4, prepare g4 and Qd2. The storm is coming — and so is yours."},{san:"h5",explanation:"The modern antidote and the move to remember: stop g4 dead. White's whole attacking scheme needed that pawn lever; one flank move by you cancels the storm before it forms. Positional prophylaxis at its finest.",principle:"Prophylaxis"},{san:"Qd2",explanation:"White continues the setup, but with g4 stopped, castling long has lost most of its teeth."},{san:"Nbd7",explanation:"Develop toward the action: this knight dreams of ...Nb6 (fighting d5) or ...Nc5 hitting e4. From here: ...Be7, ...Rc8 or ...b5 — your attack arrives on schedule, theirs never quite does."}],plans:["Complete with ...Be7, ...Rc8 (delay castling — your king is safest deciding late), then ...b5-b4 rolling first.","If White ever manages g4 anyway, ...hxg4 opens the h-file for YOUR rook — the h5 pawn wins either way.","Watch for Nd5 sacrifices; with ...Be6 posted and ...Nb6 available, the standard sacs come up short."]}]},{id:"qgd-black",name:"Queen's Gambit Declined (as Black)",eco:"D30–D69",side:"black",order:8,tagline:"Your answer to 1.d4 — the classical fortress every world champion has trusted",summary:"Against 1.d4 d5 2.c4, the move 2...e6 declines the gambit and builds an unshakeable central fortress. You'll learn the Tartakower setup (the modern professional's choice), the Carlsbad structure against the Exchange, and how to neutralize London players — a complete answer to queen's-pawn openings.",whyPlayIt:["Studying the QGD from both sides (you also study it as White here) doubles the value of every hour — you'll understand the position's soul, not just moves.","The Tartakower (...b6 and ...Bb7) solves Black's eternal problem piece, the c8 bishop, with one clean plan.","It has never been refuted in 150 years. It never will be."],keyPrinciples:["d5 is your rock: keep it defended and your position cannot collapse.","Break the Bg5 pin early with ...Be7; use ...h6 to ask the bishop its intentions.","Your freeing breaks are ...c5 and ...e5 — every piece placement should serve one of them.","The c8 bishop is the problem child: solve it via ...b6+...Bb7 (Tartakower) or trade it before ...e6 locks it (not possible here — so plan ...b6)."],commonMistakes:[{mistake:"Developing pieces without ever playing ...c5 or ...e5",why:"A QGD without a freeing break is a slow squeeze in White's favor. If you reach move 15 without one either played or prepared, something went wrong."},{mistake:"Taking on c4 too early (before White's bishop has moved)",why:"...dxc4 gains nothing if Bf1xc4 develops White for free. Take only when it wins a tempo or a concrete goal (like freeing ...Nd5 or ...c5)."},{mistake:"Ignoring the minority attack in the Carlsbad structure",why:"When White plays b4-b5 against your c6, doing nothing leaves you a permanent weak pawn. Know the antidotes: ...b5!? blockades, or kingside counterplay with ...Ne4 and ...f5."}],lines:[{id:"qgdb-tartakower",difficulty:2,name:"Tartakower Defense (Main Line)",description:"The professional's QGD: ...h6, ...b6 and ...Bb7 solve the bad-bishop problem permanently. Karpov and Carlsen have trusted this setup in world championship matches.",side:"black",moves:[{san:"d4"},{san:"d5",explanation:"Meet the center head-on. Symmetric, solid, principled.",principle:"Control the center"},{san:"c4"},{san:"e6",explanation:"Decline the gambit: d5 stays defended by a pawn forever. The cost — the c8 bishop is behind the chain — is exactly what this line's plan will fix."},{san:"Nc3"},{san:"Nf6",explanation:"Defend d5 again and develop your best defender."},{san:"Bg5",explanation:"White pins, pressuring d5 through the f6 knight."},{san:"Be7",explanation:"Break the pin immediately and calmly. The knight is free again; d5 holds.",principle:"Break pins early"},{san:"e3"},{san:"O-O",explanation:"Castle before anything fancy.",principle:"Castle early"},{san:"Nf3"},{san:"h6",explanation:"The little question: the bishop must choose. If Bxf6, you recapture with the bishop and own the dark squares; if Bh4, you've gained luft and the option of ...g5 breaks in some endgames — all for free."},{san:"Bh4",explanation:"White keeps the pin at arm's length."},{san:"b6",explanation:"The Tartakower move: the problem bishop gets the b7 home, supporting a future ...c5 and eyeing the long diagonal. Black's whole setup now makes sense.",principle:"Solve your worst piece"},{san:"Be2"},{san:"Bb7",explanation:"The bishop lives. Note it also re-defends d5 laterally in lines where ...dxc4 happens."},{san:"Bxf6",explanation:"White often trades here to fight for e4/d5 squares before Black consolidates."},{san:"Bxf6",explanation:"Recapture with the BISHOP — it becomes a monster on the long dark diagonal after the coming ...c5. Never ...gxf6? wrecking your king."},{san:"cxd5",explanation:"White clarifies the center."},{san:"exd5",explanation:"Recapture toward the center, keeping d5 as your space-holding rock. The position is equal: your bishops point at White's queenside, and ...c5 comes next.",principle:"Recapture toward the center"}],plans:["...c5! as soon as convenient — with the b7/f6 bishops raking the board, the break equalizes fully.","Rooks to c8 and e8; the ...Re8 + ...Ne4-ideas (after ...Nd7) generate kingside play.","If White wins the c-file, contest it — one pair of rook trades usually kills any pressure."]},{id:"qgdb-carlsbad",difficulty:2,name:"vs Exchange Variation (Carlsbad setup)",description:"3.cxd5 exd5 fixes the famous Carlsbad structure. You'll learn the classical defensive scheme — ...c6, ...Be7, ...Nbd7-f8 — that holds the minority attack and prepares your own kingside play.",side:"black",moves:[{san:"d4"},{san:"d5"},{san:"c4"},{san:"e6"},{san:"cxd5",explanation:"The Exchange: White fixes the structure early, planning the queenside minority attack (b4-b5). It looks harmless; it is not. Precision required."},{san:"exd5",explanation:"Recapture toward the center. Your c8 bishop's diagonal is OPEN now — one silver lining of the trade.",principle:"Recapture toward the center"},{san:"Nc3"},{san:"Nf6"},{san:"Bg5"},{san:"c6",explanation:"The Carlsbad wall: c6 shores up d5 and pre-blunts the b5 push. This pawn is the minority attack's future target — the whole middlegame revolves around it."},{san:"e3"},{san:"Be7"},{san:"Bd3"},{san:"Nbd7",explanation:"The knight begins the classical defensive tour: d7 now, f8 later (guarding h7 and freeing the e8 rook), sometimes g6 or e6 after that."},{san:"Qc2",explanation:"White's standard square: queen supports e4 ideas and eyes h7."},{san:"O-O"},{san:"Nf3",explanation:"The main line (Nge2 heading for f4/g3 is the other setup)."},{san:"Re8",explanation:"The rook takes the only open file. It also clears f8 for the knight — every Black piece has a role in the scheme.",principle:"Rooks to open files"},{san:"O-O"},{san:"Nf8",explanation:"The famous maneuver completes: h7 is covered, the c8 bishop breathes, and ...Ng6/...Ne6 plus ...Ne4 jumps are coming. Black is fully ready for the minority attack."}],plans:["Against b4-b5: consider ...b5!? yourself (stopping the attack at the cost of the c6 backward pawn being fixed — a known good trade), or counter in the center/kingside.","Your play: ...Ne4 (the dream outpost), ...Bf5 or ...Bg4 trading the bad bishop, ...Ng6 and kingside expansion.","Trade dark-squared bishops via ...Bd6-ideas only when it doesn't concede e5 to a White knight."]},{id:"qgdb-vs-london",difficulty:1,name:"vs London System",description:"London players expect autopilot; ...Bd6 challenges their bishop immediately and an early ...c5 hits the center. Play actively and their system yields nothing.",side:"black",moves:[{san:"d4"},{san:"d5"},{san:"Bf4",explanation:"The London. White wants the same setup regardless of what you do — so do something the setup least enjoys."},{san:"Nf6"},{san:"e3"},{san:"e6",explanation:"Open the f8 bishop's path. (Your c8 bishop is briefly locked, but the plan of ...Bd6 and ...b6/...c5 handles it.)"},{san:"Nf3"},{san:"Bd6",explanation:"The key move: offer the trade of White's best piece. Every London player hates this decision — trading concedes the dark squares, retreating loses time.",principle:"Challenge the opponent's best piece"},{san:"Bg3",explanation:"The usual choice: keep the bishop, offering you a free developing tempo."},{san:"O-O",explanation:"Castle first — taking on g3 immediately only opens White's h-file. The tension favors you; keep it.",principle:"Castle early"},{san:"Bd3"},{san:"c5",explanation:"Strike the center while White is still setting up. The London's d4 point is its heart — attack it before c3 fully braces it.",principle:"Attack the center"},{san:"c3"},{san:"Nc6",explanation:"Pile on d4 and develop. Black's pieces flow to natural squares while White must now watch both cxd4 tricks and the e5 outpost fight."},{san:"Nbd2"},{san:"b6",explanation:"Solve the last piece: the c8 bishop gets b7 (or a6, trading itself for White's good bishop — even better when available). Black stands fully equal with clear plans."}],plans:["...Bb7 or the sharper ...Ba6 trading light-squared bishops — the London's Bd3 is its attacking piece; swap it off.","...Qe7 and ...e5 in one go, or ...cxd4 followed by minority-style ...b5-b4.","If White ever plays Ne5, challenge it immediately with ...Nxe5 or ...Bxe5 recaptures sorted in advance."]}]},{id:"pawn-endgames",name:"Pawn Endgames: The Essentials",eco:"Endgame School I",side:"white",category:"endgame",order:100,tagline:"Opposition and key squares — every endgame education starts here",summary:"King and pawn versus king decides more club games than any other ending, and it runs on one idea: the opposition. Learn the winning technique (king leads, pawn follows) and the drawing technique (stay in front, retreat straight back) and you'll convert and save positions your opponents misplay every week.",whyPlayIt:["Every pawn-up endgame you'll ever win funnels into K+P vs K — knowing it converts a whole class of advantages.","The opposition is the single highest-value concept in endgame play, and it transfers to rook and minor-piece endings.","Both sides in two lessons: you learn to win it AND to hold the draw a pawn down."],keyPrinciples:["The king leads, the pawn follows — advance the king first, always.","Opposition: kings facing with one square between — whoever must move gives ground.","Attacker's dream: your king on the 6th rank in front of the pawn wins no matter whose move it is.","Defender's rule: stay in front of the pawn, and when it reaches the 6th, step STRAIGHT back."],commonMistakes:[{mistake:"Pushing the pawn ahead of the king",why:"The pawn can't force its own way through — every unsupported advance burns a tempo and walks toward the classic stalemate draw."},{mistake:"Defending with diagonal retreats",why:"When the pawn hits the 6th rank, ...Kd8 or ...Kf8 loses to the outflanking Kf6/Kd6. Straight back is the only holding move — it's counterintuitive, which is why it wins so many half-points."},{mistake:"Forgetting stalemate is your friend (or enemy)",why:"Half of K+P theory IS stalemate. The defender aims for it; the attacker must see it coming a move early."}],lines:[{id:"kp-king-sixth",difficulty:1,name:"The Winning Technique (king on the 6th)",description:"Your king stands on the 6th rank in front of the pawn — the textbook win. One wrong move order throws it away to stalemate; the right one promotes by force. You play White.",side:"white",startFen:"4k3/8/4K3/4P3/8/8/8/8 w - - 0 1",moves:[{san:"Kd6",explanation:"The king steps forward and to the side — clearing the pawn's path while staying ahead of it. King leads, pawn follows: this order is the entire technique.",principle:"The king leads",wrongMoves:{e6:"The classic thrown-away win: 1.e6? Kd8! 2.e7+ Ke8 and now 3.Ke6 is STALEMATE — draw. Push the king forward, not the pawn.",Kf6:"Kf6 wins too (it's the mirror image), but learn the standard route via d6 — one clean technique beats two half-known ones."}},{san:"Kd8",explanation:"Black grabs the opposition, hoping to block the queening square. With your king already on the 6th, it doesn't matter — that's why this position is winning regardless of the move."},{san:"e6",explanation:"NOW the pawn advances, with the king escorting from the side. Note it arrives without check — Black gets no free tempo.",wrongMoves:{Kc6:"Wandering sideways lets Black slide back in front with ...Ke7 and start holding. Your king has done its job — it's the pawn's turn."}},{san:"Ke8",explanation:"Forced back to guard the queening square."},{san:"e7",explanation:"The pawn reaches the 7th WITHOUT check — the detail that decides everything. Black's king is pushed off the promotion square next move.",wrongMoves:{Kc7:"No need to walk around — the pawn advancing without check wins on the spot. Count the tempi: e7 forces Black away immediately."}},{san:"Kf7",explanation:"The only legal try (d8 and f8 are covered by your pawn, d7 by your king). Black must abandon the corner office."},{san:"Kd7",explanation:"Guard the pawn and the queening square in one move. Nothing can stop e8=Q now. This exact maneuver — Kd6, e6, e7 without check, Kd7 — converts every won K+P endgame you'll ever reach.",principle:"Escort to the queening square"}],plans:["e8=Q next move — and with a queen up, drive the enemy king to the edge and mate with queen + king.","Remember the losing try: pawn first (1.e6?) walks into the stalemate draw. King first, always.","This works one file over, two files over — the pattern, not the squares, is what you've learned."]},{id:"kp-defender-draw",difficulty:1,name:"The Defender's Draw (straight back!)",description:"A pawn down in the same ending — and it's a dead draw if you know the rule: stay in front of the pawn, and when it reaches the 6th rank, retreat STRAIGHT back. You play Black and force the stalemate.",side:"black",startFen:"4k3/8/8/4K3/4P3/8/8/8 b - - 0 1",moves:[{san:"Ke7",explanation:"Take the opposition: kings face off with one square between, and White must give ground or make no progress. Staying directly in the pawn's path is the defender's whole job.",principle:"The opposition",wrongMoves:{Kd7:"Stepping aside loses: White plays Kf6! and outflanks — the king escorts the pawn home while yours watches. Stay in front.",Kf7:"Stepping aside loses: White plays Kd6! and outflanks. The defender must stay in the pawn's path — take the opposition with Ke7.",Kd8:"Too passive — White marches Kd6 with the pawn following, reaching the winning setup. Meet the king head-on: Ke7."}},{san:"Kd5",explanation:"White tries to walk around your king — the outflanking attempt."},{san:"Kd7",explanation:"Shadow him. Every sidestep gets mirrored, keeping the opposition. White's king can never reach the 6th rank in front of the pawn — which is the only winning setup.",principle:"The opposition",wrongMoves:{Ke7:"White walks around with Kc6 and escorts the pawn. Mirror the king: he went to d5, you go to d7."}},{san:"e5",explanation:"No progress by king, so White pushes — but now the pawn and king advance together without the king in front. That's the drawing pattern arriving."},{san:"Ke7",explanation:"Back in front of the pawn. Note the seesaw: you shuttle between d7/e7/e8, always blocking the file.",wrongMoves:{Kc7:"Leaving the pawn's file loses instantly — Ke6 and the pawn walks in. There is exactly one post: in front of the pawn."}},{san:"e6",explanation:"The critical moment of the whole ending: the pawn touches the 6th. Everything depends on your next move."},{san:"Ke8",explanation:"STRAIGHT BACK — the move that saves the game and the one everyone gets wrong. Now if Kd6, Kd8 takes the opposition; White's only try gives stalemate.",principle:"Straight back on the 6th",wrongMoves:{Kd8:"The famous losing retreat: 5...Kd8?? 6.Kf6! Ke8 7.e7 and White wins — your king got outflanked. When the pawn hits the 6th: STRAIGHT back, never diagonal.",Kf8:"The famous losing retreat, mirrored: 5...Kf8?? 6.Kd6! outflanks and the pawn promotes. Straight back — Ke8 — is the only drawing move."}},{san:"Kd6",explanation:"White grabs the opposition-looking square… but it's a move too late."},{san:"Kd8",explanation:"Take the opposition back. Now White's pawn can only advance with check — and that, famously, is a draw.",principle:"The opposition",wrongMoves:{Kf8:"6...Kf8?? 7.e7+?? no — 7.Kd7! and the pawn queens. Face the king: Kd8 holds because e7 then comes WITH check."}},{san:"e7+",explanation:"The pawn reaches the 7th WITH CHECK — compare the winning line, where it arrived silently. That one tempo is the whole difference between winning and drawing."},{san:"Ke8",explanation:"Blockade the queening square. White's king would love to guard e8 from d7 or f7 — both are illegal, occupied by your king's aura."},{san:"Ke6",explanation:"White's only non-losing try… and it's STALEMATE. No legal Black move exists: d7, d8, f7, f8 are all covered. Draw! You held a pawn-down ending with pure technique."}],plans:["That's the full defensive kit: opposition, mirror the sidesteps, straight back on the 6th, blockade, stalemate.","If White avoids stalemate with a different move 7, the pawn simply falls or repetition follows — the draw is airtight.","Flip it around: as the attacker, this is exactly why your king must reach the 6th BEFORE the pawn does."]},{id:"kp-square-rule",difficulty:1,name:"The Square Rule (catch that pawn!)",description:"A passed pawn races for the queening square with no king to escort it. Can yours catch it? Draw the square in your head and you'll know instantly — no counting, no panic. You play Black.",side:"black",startFen:"8/8/4k3/7P/8/8/8/K7 b - - 0 1",moves:[{san:"Kf5",explanation:"The square rule: imagine a box from the pawn to its queening square — here h5-h8-e8-e5. Your king stands inside it (e6), so the pawn is catchable by force. Step diagonally toward the chase: diagonal king moves gain ground in two directions at once.",principle:"The square rule",wrongMoves:{Kd5:"You just stepped OUT of the square (h5-h8-e8-e5)! After h6, h7, h8=Q the pawn is untouchable. Draw the square first — every king move must stay inside it.",Kd6:"Wrong direction — that leaves the pawn's square, and it simply runs: h6, h7, h8=Q. Chase diagonally toward the promotion corner.",Kf6:"Also inside the square — it catches the pawn too. But the diagonal route (Kf5) is the fastest chase and the habit worth building."}},{san:"h6",explanation:"The pawn sprints — it has no other hope. Note the square shrank with it: now h6-h8-f8-f6. Are you still inside? Yes — f5 touches it."},{san:"Kg6",explanation:"Step in FRONT of the pawn's path. The race is over: h7 next is met by taking it, and any wait lets your king plant on g7 forever.",principle:"The square rule",wrongMoves:{Kg5:"Careful — after h7! Kg6 h8=Q the pawn promotes with your king one step short. You're outside the new square (h6-f6-f8-h8); cut in FRONT with Kg6 instead.",Ke6:"Backwards! The race runs toward h8, and every step must shrink the pawn's escape. Kg6 blocks the path for good."}},{san:"h7",explanation:"The last dash…"},{san:"Kxh7",explanation:"…caught. With no white king nearby, an unescorted passer inside your square is just a decoy. Count the square before you panic — half of 'lost' pawn races are dead draws."}],plans:["The rule in one line: if your king can step into the pawn's square on your move, you catch it. Outside, it queens.","With YOUR passer, invert it: push the moment the enemy king stands outside the square.","Kings chase diagonally — one diagonal step fights for two goals at once."]},{id:"kp-outside-passer",name:"The Outside Passed Pawn (the decoy)",description:"The passer on the far wing was never meant to promote — it's a decoy that drags the enemy king across the board while YOUR king raids the other side. The most common winning method in all of pawn endgames. You play White.",side:"white",difficulty:2,startFen:"8/5kp1/8/8/P4K2/6P1/8/8 w - - 0 1",moves:[{san:"a5",explanation:"Push the decoy. Black's king MUST chase it — no one else can stop it — and every step it takes westward abandons the g7 pawn eastward. You're not promoting this pawn; you're selling it for a king.",principle:"The decoy",wrongMoves:{Ke5:"The king raid comes SECOND — first make the decoy expensive. Every square the a-pawn advances drags Black's king further from the real battlefield: a5!",Kg5:"Chasing g7 directly lets Black's king shadow you while the a-pawn sits idle. Push the decoy first and Black can't do both jobs."}},{san:"Ke7",explanation:"The chase begins — forced. Watch the geometry: the black king walks off the kingside one column per move."},{san:"a6",explanation:"Faster. Never let the chaser rest."},{san:"Kd6",explanation:"Still chasing — and now two files from the pawn it actually needs to defend."},{san:"a7",explanation:"One step from glory — which forces Black's king ALL the way to the corner to arrest it.",principle:"The decoy"},{san:"Kc7",explanation:"The arrest is imminent (…Kb7xa7 next). Perfect: the decoy did its job. Now watch where your king goes."},{san:"Kf5",explanation:"The pivot: abandon the decoy entirely and raid the kingside. Count the race — Black spends two moves capturing a7 while your king takes the express lane to g6. (Note f6 is off-limits: the g7 pawn guards it — kings route AROUND pawn cover.)",principle:"The raid",wrongMoves:{Ke5:"A step toward the center — but the race is decided by single tempi, and f5→g6 is the express lane to g7. Route around the pawn's cover, not through the middle."}},{san:"Kb7",explanation:"Committed to the arrest."},{san:"Kg6",explanation:"Knocking on the door — g7 falls next move, and note how f5→g6 slipped around the pawn's diagonal guard of f6."},{san:"Kxa7",explanation:"Black wins the decoy — a pawn that cost the whole game to catch."},{san:"Kxg7",explanation:"And the raid cashes in. Count the new race: your g-pawn queens in five (g4, g5, g6, g7, g8=Q); Black's king needs six squares just to reach the neighborhood. The outside passer never promoted — it bought the win at the till."}],plans:["March the g-pawn immediately: g4-g5-g6-g7-g8=Q — Black's king is a full tempo short. Count it every time before pivoting.","The evaluation shortcut this teaches: in king-and-pawn endgames, the OUTSIDE passer usually decides — its distance from the main pawns IS its value.","As the defender, the counter is to trade off the outside passer early — even at the cost of a kingside pawn."]},{id:"kp-queen-vs-pawn",name:"Queen vs Pawn on the 7th (the zigzag)",description:"Your queen faces a pawn one square from promotion with your king a continent away. The winning dance: checks force the enemy king IN FRONT of its own pawn, buying your king one step per cycle. You play White.",side:"white",difficulty:3,startFen:"8/8/8/K6Q/8/8/4pk2/8 w - - 0 1",moves:[{san:"Qh4+",explanation:"The zigzag begins: check from behind, herding the king toward the pawn. Note your king on a5 — hopelessly far. The whole technique exists to buy it walking time.",principle:"The zigzag",wrongMoves:{Qe5:"Eyeing the pawn — but ...e1=Q arrives NOW and it's a queen endgame draw. Every move of this technique must check or pin; start herding: Qh4+.",Kb4:"The king can't just stroll — ...e1=Q promotes immediately. The queen must freeze the pawn first; the king only moves on bought time."}},{san:"Kf1",explanation:"The king shields the pawn from beside it. Fine — the zigzag has a square prepared for every retreat."},{san:"Qh1+",explanation:"Check along the bottom rank, pushing the king off the promotion square's guard duty…",principle:"The zigzag"},{san:"Kf2",explanation:"…and back up it comes. This looks like a repetition. It isn't — watch what the NEXT check forces."},{san:"Qh2+",explanation:"The key check of the whole dance: the king's only good square now stands IN FRONT of its own pawn."},{san:"Ke1",explanation:"There it is: the king blocks e1, the pawn cannot promote, and Black has passed the move back to you with the position frozen. That frozen moment is the entire currency of this endgame."},{san:"Kb4",explanation:"The purchased tempo: your king takes ONE step. That's the whole trick — the queen alone can't win, but she can freeze the position one move per cycle while the king walks over.",principle:"Buy a tempo, spend it on the king",wrongMoves:{Qg2:"The pawn was already frozen — this wastes the bought tempo. The queen's work is done for this cycle; SPEND the move on your king: Kb4."}},{san:"Kf1",explanation:"Freed again, the king steps aside and re-threatens ...e1=Q. No matter: the dance simply repeats."},{san:"Qh1+",explanation:"Cycle two, same steps…"},{san:"Kf2"},{san:"Qh2+",explanation:"…same key check…"},{san:"Ke1",explanation:"…same freeze."},{san:"Kc3",explanation:"…and another king step, now two squares away. One more cycle brings Kd3, and then the pawn falls with mate close behind. Zigzag, freeze, step — repeat until the king arrives. One warning for your own games: against BISHOP and ROOK pawns (a/c/f/h), the defender has stalemate tricks in the corner — this clean win is for center and knight pawns."}],plans:["Next cycle ends with Kd3: the pawn is attacked twice, defended once — it falls, and Q+K mate follows in a handful of moves.","Remember the exception cold: c-, f-, a-, h-pawns on the 7th often DRAW (stalemate resources) — know which fight you're in before trading into it.","As defender: run your king toward the CORNER stalemate tricks with those pawns; with center pawns, resign yourself to the zigzag."]}]},{id:"rook-endgames",name:"Rook Endgames: Lucena & Philidor",eco:"Endgame School II",side:"white",category:"endgame",order:101,tagline:"The two positions every rook endgame flows into",summary:"Half of all endgames are rook endgames, and nearly all of them drain toward two ancient positions: the Lucena (how the extra pawn wins — 'building the bridge') and the Philidor (how the defender draws — the third-rank defense). Learn both and you own the most common endgame in chess from either chair.",whyPlayIt:["Rook endings are the most common endgame type by far — this is the highest-frequency knowledge in chess.","The Lucena bridge is a forced, five-move recipe: once seen, never lost again.","The Philidor defense turns 'a pawn down in a rook ending' from a loss into a routine draw — worth dozens of half-points."],keyPrinciples:["Lucena (winning): shelter your king on the queening square, then build a bridge — rook to the 4th rank, walk the king out, block the checks.","Philidor (drawing): park your rook on your third rank so the enemy king can't cross; the instant the pawn advances to that rank, drop the rook behind for endless checks.","Rooks belong BEHIND passed pawns — yours or theirs.","Checking distance: a rook needs three ranks of runway to harass a king forever."],commonMistakes:[{mistake:"Walking the king out of shelter before building the bridge",why:"In the Lucena, the checks chase your king back home if the rook isn't already waiting on the 4th rank. Bridge first, king second."},{mistake:"Dropping the rook back too early in the Philidor",why:"The checks-from-behind only work once the pawn stands on the 6th (blocking the king's shelter). Hold the third rank until that exact moment."},{mistake:"Trading rooks without counting the pawn ending",why:"Every rook trade converts the position into K+P theory — which you now know. Count it BEFORE the trade, not after."}],lines:[{id:"rook-lucena",difficulty:2,name:"Lucena: Building the Bridge",description:"Your pawn sits one step from queening with your king sheltered in front of it — but the king can't step out into the rain of checks. The bridge (rook to the 4th!) shelters the walk. You play White; five precise moves force the win.",side:"white",startFen:"4K3/4P1k1/8/8/8/8/4r3/5R2 w - - 0 1",moves:[{san:"Rf4",explanation:"The famous bridge-building move — and it looks completely pointless. The rook takes the 4th rank so that when your king walks out into checks, it can interpose at e4. Preparation before action.",principle:"Build the bridge",wrongMoves:{Kd7:"Too early! Kd7? Rd2+ Ke6 Re2+ and the checks drive your king right back to e8 — there's no shelter anywhere. Build the bridge FIRST: rook to the 4th rank.",Kf7:"The rook checks you forever after Rf2+ — and your king has nowhere to hide. Prepare the shelter first: rook to the 4th rank."}},{san:"Re1",explanation:"Black can only wait, keeping the rook on the e-file to stop the promotion. There are no checks and no better squares — which is exactly why the bridge wins by force."},{san:"Kd7",explanation:"NOW the king steps out — the bridge is ready. Let the checks come.",principle:"King leaves shelter",wrongMoves:{e8:"The king is standing on e8 — the pawn can't promote until it moves! That's the entire problem the bridge solves: walk the king out under cover."}},{san:"Rd1+",explanation:"The checks begin, as they must — Black's only source of counterplay."},{san:"Ke6",explanation:"Zigzag down the board, closing in on your rook's rank with every step. The king approaches the bridge."},{san:"Re1+",explanation:"Check again — Black has nothing else."},{san:"Kd6",explanation:"Keep zigzagging. Notice the pattern: each check pushes you one rank closer to e4, where the shelter waits."},{san:"Rd1+",explanation:"The rook keeps barking…"},{san:"Ke5",explanation:"…and the king arrives next door to the bridge. One more check is all Black has left."},{san:"Re1+",explanation:"The final check."},{san:"Re4",explanation:"The bridge closes! The rook interposes, the checks are over, and e8=Q cannot be stopped — if ...Rxe4+ then Kxe4 and the pawn promotes anyway. Five moves, zero calculation: that's why this technique has survived since 1497.",principle:"Build the bridge"}],plans:["Promotion is forced: ...Rxe4+ Kxe4, pawn queens; anything else, e8=Q immediately.","The recipe generalizes: rook to the 4th rank, king out, zigzag toward the rook, interpose. Any file, either color.","If the defender's king were closer, the bridge still works — the checks always run out at the 4th rank."]},{id:"rook-philidor",difficulty:2,name:"Philidor: The Third-Rank Defense",description:"A pawn down in a rook ending — the nightmare that isn't. Hold your third rank so the king can't cross, and the moment the pawn advances, drop your rook behind for perpetual checks. You play Black; the draw is bulletproof.",side:"black",startFen:"4k3/R7/1r6/4K3/4P3/8/8/8 w - - 0 1",moves:[{san:"Kd5",explanation:"White's king tries to lead the pawn forward — the standard winning attempt."},{san:"Rc6",explanation:"The Philidor stance: shuffle along YOUR third rank (the 6th). As long as the rook patrols this rank, White's king can never step to d6 or f6 — and without the king in front, the pawn can't win.",principle:"Hold the third rank",wrongMoves:{Rb1:"Too soon! The checks from behind only work when the pawn blocks its own king's shelter on e6. Right now White's king simply hides at d6 — hold the 6th rank until the pawn commits.",Rb5:"Pinning tries lose the rook's job: after Kc4 the king crosses next move. The rook has ONE post — the third rank — until the pawn advances."}},{san:"e5",explanation:"The pawn advances with the king, but note: the king still can't cross the 6th rank thanks to your rook."},{san:"Rb6",explanation:"Just shuffle. Waiting is winning (well — drawing): White cannot improve as long as the rank is held. Patience is the technique.",principle:"Hold the third rank",wrongMoves:{Rc1:"One move early again — the pawn is only on the 5th. After Kd6! the king shelters in front of its pawn and wins. The trigger is the pawn touching YOUR third rank."}},{san:"e6",explanation:"There it is — the pawn steps onto the 6th rank. It now blocks the ONLY shelter its own king had. This is the moment the entire defense pivots on."},{san:"Rb1",explanation:"Drop to the first rank instantly. The rook's job flips from wall to sniper: with the pawn occupying e6, White's king has no hiding square from checks anywhere on the board.",principle:"Checks from behind",wrongMoves:{Ra6:"The waiting game just ended — after Kd6 the king walks in and it's over. The pawn on the 6th is your signal: rook to the 1st rank, NOW.",Rc6:"The waiting game just ended — Kd6 wins if you keep shuffling. Pawn on the 6th = rook drops behind for checks. That's the whole system."}},{san:"Kd6",explanation:"White heads for the queening ceremony… into the hail."},{san:"Rd1+",explanation:"Check. Where can the king go? Not e7/d7-shelter — the pawn took e6, remember.",principle:"Checks from behind"},{san:"Ke5",explanation:"The king tries the other wing…"},{san:"Re1+",explanation:"…check again, harassing from three ranks' distance. The rook never runs out of runway."},{san:"Kf6",explanation:"One more try…"},{san:"Rf1+",explanation:"…and one more check. The pattern is eternal: approach the rook and it slides away; hide behind the pawn and there IS no behind — e6 is occupied. Draw, as it has been since 1777.",principle:"Checks from behind"}],plans:["The checks never end: if the king approaches your rook, slide to the far side and keep checking — three ranks of distance is unlimited ammunition.","If White ever blocks with the rook (Rf7-ish ideas), trade into the K+P ending — which you hold with the straight-back technique from Endgame School I.","The two triggers to memorize: rook holds YOUR third rank; pawn reaches it → rook drops behind. That's the entire defense."]}]},{id:"fortress-draws",name:"Fortress Draws: Saving Lost Positions",eco:"Endgame School III",side:"black",category:"endgame",order:102,tagline:"Down a piece or a pawn — and completely safe. Stalemate is your friend",summary:"Some 'lost' positions are stone-cold draws if you know where the fortress is. The rook-pawn corner and the wrong-colored bishop save countless half-points because the attacker's extra material simply cannot break in — every winning try ends in stalemate. Learn to recognize them from both sides: hold them as the defender, avoid them as the attacker.",whyPlayIt:["These draws are pure knowledge — zero calculation over the board once you know the pattern.","Attackers need them too: trading into a rook-pawn or wrong-bishop ending throws away a whole winning position.","Stalemate awareness is the last skill club players develop — these lessons build it directly."],keyPrinciples:["Rook pawns are different: the board has no 'other side' to outflank from.","Corner rule: if the defending king reaches the queening corner of a rook pawn, it can never be evicted.","Wrong bishop: a bishop that doesn't control the rook pawn's queening square can never win it — the corner is a fortress.","The defender WANTS stalemate — steer into it; the attacker must see it a move early."],commonMistakes:[{mistake:"Leaving the corner to 'do something'",why:"The fortress works because g8/h8 (or the mirror) can't be covered by the attacker. Step out once and the door slams shut behind you — the king often can never return."},{mistake:"As the attacker: trading into these endings a pawn up",why:"Before simplifying, check which rook pawn and which bishop you'll be left with. 'Winning' the exchange into a wrong-bishop corner is a classic half-point gift."},{mistake:"Forgetting the defender's king must actually REACH the corner",why:"These are draws only from inside the fortress. If the attacking king can cut you off first, the same material wins — the race to the corner is the whole game."}],lines:[{id:"fd-rook-pawn",difficulty:1,name:"The Rook-Pawn Corner",description:"King and rook pawn against a lone king — a win everywhere on the board except the h-file. From the corner, the defender cannot lose. You play Black: shuffle, and let White stalemate you.",side:"black",startFen:"6k1/8/7K/7P/8/8/8/8 b - - 0 1",moves:[{san:"Kh8",explanation:"Into the corner — the one unbreakable square. Against any other pawn White would outflank around the far side; against a rook pawn there IS no far side. The h8 corner is the whole fortress.",principle:"Corner fortress",wrongMoves:{Kf8:"Fatal! 2.Kh7 seizes the corner and the pawn strolls home behind the king. Against a rook pawn the corner IS the defense — only g8 and h8 hold.",Kf7:"2.Kh7! and White owns g8/h8 — the pawn promotes untouched. Get INTO the corner: Kh8."}},{san:"Kg6",explanation:"White probes, dreaming of g7 — but your next shuffle keeps the box sealed."},{san:"Kg8",explanation:"The eternal shuffle: g8, h8, g8, h8. White's king may never step to g7 while you stand on g8, and the pawn can't promote while you hold the corner. There is no zugzwang — you always have the other square.",principle:"Corner fortress"},{san:"h6",explanation:"The pawn advances — closer, but no wiser. Watch what its own march does to White's winning chances."},{san:"Kh8",explanation:"Back to the corner on cue. White's king guards the pawn, the pawn blocks the king — they're in each other's way forever.",wrongMoves:{Kf8:"Stepping out now loses on the spot: 4.h7! and your king can never touch g8 again (the pawn covers it) — White promotes at leisure. The shuffle is g8↔h8, nothing else, ever."}},{san:"h7",explanation:"…and it's STALEMATE — your king has no legal move: g8 is covered by the pawn, g7 by the king, and the pawn itself is defended. White's only alternative was to abandon the pawn or repeat forever. Draw, from a king down to nothing."}],plans:["The whole defense: reach g8/h8, then shuffle between them. Nothing else required, nothing else allowed.","As the attacker, remember the diagnosis: rook pawn + defender in the corner = dead draw. Keep another pawn on the board at all costs.","The same fortress holds against king + rook pawn + WRONG bishop — next lesson."]},{id:"fd-wrong-bishop",difficulty:2,name:"The Wrong Bishop",description:"White has an extra bishop AND the pawn — and still can't win, because the bishop travels on the wrong color and can never cover the dark queening corner. You play Black: sit tight and collect the half point.",side:"black",startFen:"7k/8/6KP/8/8/8/4B3/8 b - - 0 1",moves:[{san:"Kg8",explanation:"Hold the corner box. Look at the colors: h8 is a DARK square, and White's bishop lives on LIGHT squares — it can attack every square on the board except the one that matters. That mismatch is the entire draw.",principle:"Wrong-colored bishop"},{san:"h7+",explanation:"White pushes with check, hoping you'll step the wrong way. There's exactly one drawing square."},{san:"Kh8",explanation:"Into the corner, always. The bishop can shepherd the pawn everywhere except h8 — and a pawn on h7 with your king on h8 is a wall White built against himself.",principle:"Corner fortress",wrongMoves:{Kf8:"You locked yourself OUT — the h7 pawn covers g8 forever, so your king can never return. White's king walks to g7 and escorts the promotion. The corner (Kh8) was the only home."}},{san:"Kh6",explanation:"White's last idea… STALEMATE. g7 and g8 are covered, the h7 pawn is defended, and your king has nowhere to go. The bishop watched helplessly from the wrong color the entire game. Draw — remember this pattern from BOTH sides of the board."}],plans:["Diagnosis checklist: rook pawn + bishop that doesn't match the queening corner's color + defender's king in the corner = draw, always.","As the attacker: NEVER trade down to your bishop's wrong rook pawn. Check the corner color before every simplification.","If the defender's king can't reach the corner in time, it's a win — so as defender, sprint there first."]}]},{id:"checkmate-school",name:"Checkmate School",eco:"Endgame School IV",side:"white",category:"endgame",order:103,tagline:"The three mates that finish every won game",summary:"Winning a piece means nothing if you can't finish. These three techniques — the two-rook ladder, the king-and-rook box, and the queen's shadow — convert every winning material edge into an actual handshake. Each is a mechanical recipe: learn the pattern once and you'll never stall out a won endgame again.",whyPlayIt:["Every won game funnels into one of these three finishes — they're the cash register of chess.","Each is pure pattern, zero calculation: ladder, box, shadow. Drill them until your hands know them.","Knowing the mate changes your middlegame: you trade down CONFIDENTLY when ahead."],keyPrinciples:["Ladder (two rooks): alternate ranks like climbing rungs — the king never gets back past a rook.","Box (king + rook): the rook fences a rank, your king walks up, and when kings face off — check!","Shadow (queen): keep the queen a knight's-move from their king to shrink the cage without stalemate risk.","Stalemate is the ONLY way to ruin these — always confirm the defender has a move before you 'wait'."],commonMistakes:[{mistake:"Checking aimlessly instead of following the recipe",why:"Random checks let the king run to the center and cost dozens of moves. Each technique needs exactly one idea repeated — cut, approach, push."},{mistake:"Queen mates: hugging the king too close",why:"The queen one square away is the classic stalemate trap. A knight's-move away controls just as much while always leaving the king one legal square."},{mistake:"Forgetting the waiting move in the rook mate",why:"When your king is placed but it's the wrong player to move, pass the tempo with a rook slide along the SAME rank. Without it you chase the king forever."}],lines:[{id:"mate-ladder",name:"The Ladder Mate (two rooks)",description:"Two rooks mate without any help from their king — they simply climb: one cuts, the other checks, rank by rank until the edge. The first mate every player should own. You play White.",side:"white",difficulty:1,startFen:"8/8/8/4k3/8/8/1R6/R5K1 w - - 0 1",moves:[{san:"Rb5+",explanation:"The first rung: check on the rank drives the king back one row. Note the other rook already fences rank... this is the whole plan — the rooks take turns being the fence and the ladder.",principle:"The ladder",wrongMoves:{Ra5:"Same idea, wrong rook order — now your rooks are on the same side and can bump into each other. Lead with the CLOSER rook: Rb5+, keeping Ra1 free for the next rung.",Kf2:"The king isn't needed at all in this mate — that's the ladder's beauty. Start climbing: Rb5+."}},{san:"Ke6",explanation:"The king retreats — rank 5 is now a wall it can never re-cross."},{san:"Ra6+",explanation:"Second rung: the back rook leapfrogs to check on rank 6. The rooks alternate — fence, ladder, fence, ladder.",principle:"The ladder",wrongMoves:{Rb6:"Check — but now BOTH rooks stand on the king's side of the board and the ladder has no next rung. Alternate rooks: the one from a1 climbs."}},{san:"Ke7",explanation:"Driven again. If the king ever runs TOWARD your rooks, just slide the attacked rook far away along its rank — the wall works from any distance."},{san:"Rb7+",explanation:"Third rung. The pattern should feel mechanical by now — that's the point.",principle:"The ladder"},{san:"Ke8",explanation:"The edge of the board. Nowhere left to retreat."},{san:"Ra8#",explanation:"Checkmate! The b7 rook seals rank 7, the a8 rook delivers on rank 8. Total cost: four moves, zero thinking. That's the ladder — climb it every time you're two rooks up."}],plans:["If the king attacks a rook mid-ladder, slide that rook to the far side of the SAME rank and keep climbing.","Works identically with rook + queen, or two queens (even easier).","Practical rule: with two rooks up, ignore everything else and ladder immediately."]},{id:"mate-rook-box",name:"King + Rook: The Box",description:"One rook can't mate alone — it needs your king as a partner. Learn the fence, the shoulder-to-shoulder opposition, and the famous waiting move. You play White.",side:"white",difficulty:2,startFen:"8/3k4/8/3K4/8/8/8/7R w - - 0 1",moves:[{san:"Rh7+",explanation:"Fence first: the rook takes the 7th rank, locking the king onto the back rank forever. From here the rook barely moves — your KING does the work.",principle:"The box",wrongMoves:{Rh8:"Too far — the king isn't ON the 8th yet, so the rook fences nothing and Kd7 shoulders it away next. Fence the rank the king stands on: Rh7+."}},{san:"Kd8",explanation:"Confined to the back rank. Now the mating dance: your king seeks direct opposition — face to face, one square apart."},{san:"Kd6",explanation:"Opposition! Kings face off d6–d8. If it were mate-in-one now it would need Black to be... exactly. Black must step aside, and you'll follow.",principle:"The opposition"},{san:"Kc8",explanation:"The sidestep. Follow directly? No — first, watch what happens on the next move…"},{san:"Rg7",explanation:"THE WAITING MOVE — the star of this whole technique. The rook slides along the 7th, changing nothing except whose turn it is. Now Black must keep moving while your setup stands still. Every rook mate hinges on this tempo trick.",principle:"The waiting move",wrongMoves:{Kc6:"Chasing directly lets the king slide back with Kd8 forever — you'll dance all night. Pass the move instead: slide the rook along the 7th and make BLACK commit first.",Rh8:"Rh8+? Kb7 and the king escapes the back rank around your rook — the fence broke. Keep the rook ON the 7th; just slide it sideways to lose a tempo."}},{san:"Kb8",explanation:"Black drifts toward the corner — the only direction left."},{san:"Kc6",explanation:"Shadow the king. You're herding it into the corner where the final opposition awaits."},{san:"Ka8",explanation:"Cornered."},{san:"Kb6",explanation:"Take the final post. Black has exactly one legal move — which walks straight into the opposition."},{san:"Kb8",explanation:"Forced — and now the kings face off b6–b8 with Black having just moved. The mating position is set."},{san:"Rg8#",explanation:"Checkmate! Rook checks along the 8th; your king personally covers a7, b7, and c7. Fence → opposition → waiting move → mate: the complete one-rook recipe."}],plans:["The recipe: fence the king's rank, walk your king to opposition, pass the tempo with a rook slide, check on the edge.","If the king attacks your rook: slide to the far end of the same rank — the fence holds from any distance.","This is the mate you'll actually use most — every rook endgame you win ends here."]},{id:"mate-queen-shadow",name:"Queen Mate: The Shadow Method",description:"The queen shrinks the cage alone by staying a knight's-move from the enemy king — the one distance that can never stalemate. Then your king strolls up for the handshake. You play White.",side:"white",difficulty:2,startFen:"8/8/8/4k3/8/8/8/4KQ2 w - - 0 1",moves:[{san:"Qd3",explanation:"Take the shadow post: d3 is a knight's-move from e5. From this distance the queen fences a huge L-shaped cage while ALWAYS leaving the king a move — stalemate-proof by geometry.",principle:"The knight's-move shadow",wrongMoves:{Qf5:"Hugging the king face-to-face — the king just steps away and you've gained nothing, plus this closeness is exactly how accidental stalemates happen. Shadow from a knight's-move away: Qd3.",Qe2:"Passive — the cage doesn't shrink. The queen leads this mate; put her a knight's-move from the king: Qd3."}},{san:"Ke6",explanation:"The king retreats — and watch what your queen does: she mirrors the move, keeping the exact knight's-move distance."},{san:"Qd4",explanation:"Mirror. King went up one, queen goes up one. The shadow never touches, never lets go.",principle:"The knight's-move shadow"},{san:"Ke7"},{san:"Qd5",explanation:"Mirror again. Notice the cage: the king is being squeezed toward the back rank without a single check being thrown."},{san:"Ke8",explanation:"The king reaches the edge. IMPORTANT: the queen now STOPS — one more shadow step would risk the famous stalemate. Her job is done; the cage is sealed."},{san:"Ke2",explanation:"King's turn. The queen holds the cage (d-file, 5th rank, both diagonals) while your king marches up to deliver the final blow. No rush — Black can only shuffle between two squares.",principle:"King joins the attack",wrongMoves:{Qd7:"STALEMATE ALERT territory — crowding the caged king is how won games become draws. The queen's work is DONE; bring your king: Ke2.",Qe5:"Check achieves nothing — the king just shuffles and you've lost a tempo. Park the queen, walk the king."}},{san:"Kf8"},{san:"Kf3",explanation:"March."},{san:"Ke8"},{san:"Kf4",explanation:"March. The shuffle on the back rank is all Black has — e8, f8, e8, f8."},{san:"Kf8"},{san:"Kf5",explanation:"Almost there."},{san:"Ke8"},{san:"Kf6",explanation:"The king takes the killer post — controlling e7, f7, and g7. Black's next move is forced, and then the curtain falls."},{san:"Kf8",explanation:"Forced — d8 and d7 belong to the queen, e7 to your king."},{san:"Qd8#",explanation:"Checkmate! The queen sweeps to the back rank; your king covers every escape. Shadow → park → march → mate. This exact dance wins every queen endgame you'll ever reach."}],plans:["The full recipe: shadow at a knight's-move until the king hits the edge, PARK the queen, march your king, mate on the rank.","Stalemate self-check: before every quiet move, ask 'does the caged king still have a square?'","With queen vs anything, trade into this: it's the simplest guaranteed finish in chess."]}]},{id:"middlegame-school",name:"Middlegame School: Classic Plans",eco:"Middlegame I",side:"white",category:"middlegame",order:90,tagline:"The four plans that win middlegames when no tactic is on the board",summary:"Openings end, and suddenly nobody tells you what to do. These four scripted plans are the middlegame's greatest hits: the minority attack that manufactures a weakness, the seventh-rank invasion, the opposite-castling pawn storm, and the knight that moves in and never leaves. Learn to recognize the position each plan belongs to, and 'I don't know what to do' disappears from your games.",whyPlayIt:["Plans beat moves: a mediocre plan consistently followed outscores brilliant moves with no direction.","Each lesson is a pattern you'll recognize forever — these exact structures appear in millions of games.","They chain with your openings: the Carlsbad minority attack IS the QGD Exchange you already drill."],keyPrinciples:["Read the pawn structure first — it tells you which side of the board is yours.","Create a weakness before you attack one: no target, no plan.","Invasion squares (the 7th rank, outpost holes) are worth more than pawns.","When castled on opposite sides, the attack is a RACE — count tempi, not material."],commonMistakes:[{mistake:"Attacking where you're weaker because 'attack' sounds active",why:"Plans follow structure: pawn majorities and space tell you which wing is yours. Storming the wrong wing just opens lines against yourself."},{mistake:"Winning the plan's target immediately and releasing the pressure",why:"A fixed weakness ties enemy pieces down forever — often worth more than capturing it. Harvest when it wins by force, not the first moment it's possible."},{mistake:"Ignoring the opponent's plan while executing yours",why:"Every plan lesson here has a counter-plan for the other side. The middlegame is two plans racing — check the speedometer on theirs every move."}],lines:[{id:"mg-minority-attack",name:"The Minority Attack",description:"The Carlsbad structure's signature plan: throw your TWO queenside pawns at their THREE, trade them off, and leave one permanent weakling behind. You play White; watch c6 become a lifelong patient.",side:"white",difficulty:2,startFen:"r2q1rk1/pp1n1ppp/2pb1n2/3p4/3P4/2N1PN2/PPQ2PPP/R4RK1 w - - 0 12",moves:[{san:"b4",explanation:"The minority attack begins: two pawns march against three. It sounds backwards — but the goal isn't to win pawns, it's to TRADE them until Black's c-pawn stands alone and undefendable.",principle:"Create a weakness",wrongMoves:{e4:"The central break is the OTHER Carlsbad plan — real chess, and strong! But this lesson drills the minority attack. Start the march: b4.",a4:"Right wing, wrong order — b4 first, then a4 supports b5. Lead with the b-pawn."}},{san:"Re8",explanation:"Black follows the mirror plan: pieces toward the kingside, dreaming of ...Ne4 and an attack on your king. Two plans, two wings — the race is on."},{san:"a4",explanation:"Support the spearhead: b5 will come with backup so ...cxb5/axb5 keeps the queenside tension in your favor."},{san:"Nf8",explanation:"The Carlsbad regroup you know from the Black side — the knight heads for g6/e6. Black is playing HIS plan; you must simply be faster or steadier."},{san:"b5",explanation:"The lever lands on c6. Black faces three sad options: take (opening your files), let you take (creating the weak pawn), or push ...c5 (leaving d5 backward).",principle:"Create a weakness"},{san:"Ng6",explanation:"Black continues kingside — declining to react. Fine: you'll decide the queenside's shape yourself."},{san:"bxc6",explanation:"Trade! This is the whole point of the operation…"},{san:"bxc6",explanation:"…and there it is: the backward c6 pawn on a half-open file, defensible only by pieces. That pawn is now a chronic condition — Black's pieces will babysit it for the rest of the game."},{san:"Rab1",explanation:"Seize the newly opened file immediately (the a1 rook, so the f1 rook can follow). The b-file plus the c6 target = your entire middlegame, pre-planned.",principle:"Rooks to open files"},{san:"Rb8",explanation:"Black contests the file — but defending c6 AND the b-file with the same few pieces is exactly the overload the plan creates."},{san:"Na2",explanation:"The knight reroutes: a2 looks silly for exactly one move — then Nb4 arrives, attacking c6 AND d5 from a square no pawn can ever challenge. Minority attack complete: now it's siege warfare, and you own the siege engines.",principle:"Improve your worst piece"}],plans:["Trade one pair of rooks on the b-file, keep one to invade b7; add Qc2/Rb1+Nc5 pressure on c6.","Watch Black's kingside race: meet ...Ne4 with Nxe4 dxe4 (his structure worsens further).","Winning c6 usually converts; but even unclaimed it wins — every Black piece guarding a pawn is a piece not attacking you."]},{id:"mg-seventh-rank",name:"The Seventh-Rank Invasion",description:"One open file, one rook, total paralysis: land on the 7th rank where every enemy pawn lives, and watch the whole position kneel. You play White — and learn the hardest part: not rushing.",side:"white",difficulty:1,startFen:"r5k1/p4ppp/1p6/8/8/1P4P1/P3PP1P/2R3K1 w - - 0 1",moves:[{san:"Rc7",explanation:"The only open file leads to the 7th rank — the street where all the pawns live. From c7 the rook attacks a7 AND f7 at once, and Black's rook is chained to defense forever.",principle:"The seventh rank",wrongMoves:{Rc2:"Halfway measures — the rook is passive on c2. The 7th rank is the destination; go all the way: Rc7.",Kf1:"King moves have their day (in the endgame proper), but an open-file invasion outranks everything: Rc7 first."}},{san:"Kf8",explanation:"Black rushes the king back to defend — the standard reaction, and already a concession: defense is now Black's whole life."},{san:"Rb7",explanation:"Slide along your rank: now b6 AND a7 are both attacked, and the a8 rook must guard a7 while the pawn guards b6's neighbor — everything Black owns defends something.",principle:"The seventh rank"},{san:"a5",explanation:"Black tries to shed a weakness by advancing — but pushed pawns just become targets on new squares."},{san:"Kg2",explanation:"The move that separates club players from strong ones: NO RUSH. Black can barely move a piece without losing something, so improve your king first. Total restraint, total domination — the 7th-rank rook wins slowly and inevitably.",principle:"Don't rush a won position",wrongMoves:{Rxb6:"It wins a pawn — and sells the bind. After Rxb6 Black's rook finally gets active (...Rxa2 next), turning total domination into a messy pawn-up scramble. Improve your king first; the pawns aren't going anywhere."}}],plans:["Bring the king toward the center, THEN harvest: b6 and a5 can't both survive.","If Black's rook ever leaves a8, take a7 — then the rook returns to passivity a pawn poorer.","The pattern to remember: rook on the 7th + patient king = endgames that win themselves."]},{id:"mg-pawn-storm",name:"Opposite Castling: The Pawn Storm",description:"You castled long, they castled short — now every kingside pawn you own is a missile with no risk to your king. You play White. This is a race, and slow loses.",side:"white",difficulty:2,startFen:"r4rk1/pppq1ppp/2npbn2/8/3NP3/2N1B3/PPPQ1PPP/2KR3R w - - 0 12",moves:[{san:"h4",explanation:"The storm begins. With kings on opposite wings, your kingside pawns aren't shelter — they're ammunition. Every advance pries at the enemy king and costs your own nothing.",principle:"Opposite castling is a race",wrongMoves:{a3:"Pawn moves in FRONT of your own king loosen the bunker for nothing. Storm THEIR side: h4.",Kb1:"A wise little move in quiet positions — but this is a race, and Kb1 is a lost tempo. h4 immediately."}},{san:"Rfe8",explanation:"Black develops 'normally' — a fatal pace error in a race position. Every quiet move here is a free rung on your ladder."},{san:"h5",explanation:"Faster. The pawn eyes h6 and gains space; the h1 rook is already on the file behind it — the storm brings its own artillery."},{san:"Rab8",explanation:"Black finally starts the counter-storm plan (...b5-b4). Correct idea — two moves too late."},{san:"h6",explanation:"Contact! Black must now weaken the king's shelter one way or another: ...g6 leaves the dark squares gasping; ignoring it lets hxg7 rip the roof off.",principle:"Pry open the shelter"},{san:"g6",explanation:"The 'solid' reply — but look at f6 and the h6-square: dark-square holes that never heal. Your pieces have new homes next to their king."},{san:"Rh4",explanation:"The rook lift: h4 now, doubling with Rdh1 next, and g4-g5 or a sacrifice on g6 to follow. The file will open — the only question is which battering ram you choose. Meanwhile Black's queenside counterplay hasn't fired a shot.",principle:"Bring everyone to the party"}],plans:["Double on the h-file (Rdh1), then open it: g4-g5xf6, or the thematic Nd4-f5 / Bxh6-style strikes.","Count the race every move: if ...b4 comes, answer with a FASTER attacking move, not a defensive one — Nce2 only when forced.","Trade off defenders of the dark squares (their f6-knight is the king's best friend — remove it)."]},{id:"mg-outpost",name:"The Octopus: Installing an Eternal Knight",description:"A hole in their position is only a hole if you can occupy it — and the guard must be removed first. You play White: trade off the defender, tour the knight in, and plant it on d6 forever.",side:"white",difficulty:2,startFen:"3r2k1/1p2bppp/p3p3/4P3/8/5N2/PP3PPP/2BR2K1 w - - 0 1",moves:[{san:"Bg5",explanation:"See the hole at d6 — protected by pawns never (c- and e-pawns can't reach) but guarded by the e7 bishop. The plan starts by REMOVING THE GUARD: offer the trade the defender can't decline.",principle:"Trade the defender first",wrongMoves:{Nd2:"Rd2... check the d-file — the rook on d8 stares straight at d2. The knight's route matters, but first things first: the d6-hole has a guardian on e7. Trade it off with Bg5.",Ng5:"The bishop on e7 simply takes it — you've traded your touring knight for nothing. The BISHOP does the trading here: Bg5."}},{san:"Bxg5",explanation:"Declining loses time and the bishop pair does nothing here — Black trades, and the d6-hole's only guardian leaves the board."},{san:"Nxg5",explanation:"Recapture, and the tour begins. Watch the route: g5 → e4 → d6. Knights reach outposts by scenic paths — plan the whole journey before move one."},{san:"Kf8",explanation:"Black senses the invasion and rushes the king across. Too slow — the tour is only two stops."},{san:"Ne4",explanation:"Second stop. The knight eyes d6 from its last staging square, and nothing Black owns can cover that square ever again.",principle:"The knight tour"},{san:"Ke7",explanation:"The king personally guards d6 — the last defense. But watch what happens: your e5 pawn makes the square untouchable even by royalty."},{san:"Nd6",explanation:"The octopus lands. Protected by the e5 pawn, the knight attacks b7 and f7 simultaneously — and the king standing next to it CANNOT take (e5 guards it). One piece now outworks Black's entire army.",principle:"The outpost"},{san:"Rb8",explanation:"Total passivity: the rook babysits b7, the king is trapped guarding f7, and every white piece is free. This is what a won middlegame looks like with equal material."}],plans:["Harvest at leisure: Rd1-d3-b3 (or f3) piles on whichever pawn the octopus watches.","Never trade the octopus for less than a rook — its value is the paralysis, not its 3 points.","The full pattern: spot the hole → remove its guard → tour the knight → own the game."]},{id:"mg-greek-gift",name:"The Greek Gift: Bxh7+!",description:"The most famous sacrifice in chess: give the bishop, drag the king out, and let knight and queen arrive with tempo after tempo. You play White — and learn the checklist that tells you when the gift is sound.",side:"white",difficulty:3,startFen:"r1bq1rk1/pp1nbppp/4p3/2ppP3/3P4/2PB1N2/PP3PPP/R1BQ1RK1 w - - 0 10",moves:[{san:"Bxh7+",explanation:"The gift. The checklist that makes it sound: bishop aiming at h7 ✓, knight ready for g5 ✓, queen's path to h5 open ✓, e5 pawn keeping defenders off f6 ✓, and no black knight on f6 ✓. All five boxes ticked — so the bishop goes in.",principle:"The Greek Gift checklist",wrongMoves:{Ng5:"Right idea, wrong order — after Ng5, ...h6! evicts the knight and the moment is gone forever. The bishop CHECK comes first: it forces the king onto h7 so everything else arrives with tempo."}},{san:"Kxh7",explanation:"Declining loses a clean pawn for nothing, so the king takes — and steps onto the square where the whole army has appointments."},{san:"Ng5+",explanation:"Tempo one: check. The king must choose a retreat, and both main squares have prepared receptions (Kg6 walks into Qg4/Qd3+ storms — g8 is the 'safe' one)."},{san:"Kg8",explanation:"Back home — but the door no longer closes."},{san:"Qh5",explanation:"Tempo two: the queen arrives with the one-move threat Qh7#. Black has exactly one defensive try.",principle:"Attack with tempo",wrongMoves:{Qg4:"Eyeing g7 — but ...f5! blocks the diagonal and the attack stalls. Qh5 threatens mate in ONE (Qh7#), which permits no slow defense."}},{san:"Nf6",explanation:"The only defense: the knight blocks the h5-h7 route by attacking your queen. It costs a piece — watch why."},{san:"exf6",explanation:"The e5 pawn — the quiet hero of the checklist — removes the defender and renews Qh7# in the same move.",principle:"Remove the defender",wrongMoves:{Qxf7:"Qxf7+?? Rxf7 and the attack is over — you're just down a bishop. The f6 knight is the problem; the e-pawn was built to remove it: exf6."}},{san:"Bxf6",explanation:"Black regains the piece… and blocks his own king's last flight square in the process. Count the escape squares around g8: there are none."},{san:"Qh7#",explanation:"Checkmate. f7 and f8 are blocked by Black's own pieces, h8 is covered, and the queen on h7 is protected by the g5 knight. Bishop for a king — the oldest trade in chess. Run the checklist before every Bxh7+ you ever play; when all five boxes tick, it simply works."}],plans:["The checklist, forever: Bd3 ✓ Nf3 ✓ Qd1-h5 clear ✓ pawn e5 ✓ no ...Nf6 ✓ — sacrifice with confidence.","If Black tries 2...Kg6 instead: Qd3+/Qg4 with f7/e6 collapsing — sharper but winning; know it exists before you sac.","Missing a checklist item? Then Bxh7+ is just a blunder — the discipline IS the weapon."]},{id:"mg-iqp-break",name:"The IQP Break: d4-d5!",description:"The isolated queen's pawn is a weakness that plays like a strength — its whole life builds toward one liberating advance. You play White: time the break, and watch a static target become an avalanche.",side:"white",difficulty:2,startFen:"r1bq1rk1/pp2bppp/2n1pn2/8/2BP4/2N2N2/PP3PPP/R1BQ1RK1 w - - 0 10",moves:[{san:"d5",explanation:"The break the whole IQP setup exists for. The 'weak' pawn advances, attacks e6, and every white piece behind it — bishop on c4, knights, the d1 rook-to-be — springs open at once. Timing rule: break when your pieces outnumber theirs in the center.",principle:"The isolani's dream",wrongMoves:{Bg5:"Good developing pressure — but the lesson's moment is NOW, while every white piece points at the center. Delay and Black plays ...Nb4-d5, blockading the pawn forever: d5!"}},{san:"exd5",explanation:"Declining leaves d6/dxe6 wrecking Black's structure, so Black takes — and opens the lines you built for."},{san:"Nxd5",explanation:"Recapture with the knight, arriving in the center with threats. Notice what the break bought: the 'weakness' is gone, and activity remains."},{san:"Nxd5",explanation:"Black trades the centralized knight — nearly forced, but every trade opens YOUR lines further."},{san:"Bxd5",explanation:"The bishop recaptures onto a dream diagonal — hitting f7 and pressuring c6 and b7. Total transformation: three moves ago you had a static weakness; now you have the bishop pair aimed at the king and the only active pieces on the board. That trade — structure for activity — is the entire economics of the IQP.",principle:"Structure for activity"}],plans:["Follow with Qb3 (piling on f7/b7), Bg5, and rooks to d1/e1 — the open lines are the pawn's inheritance.","The mirror lesson as Black: BLOCKADE d5 with a knight early and the break never comes — then the IQP is just weak.","General rule for all pawn breaks: count the pieces supporting vs. restraining the break square. More supporters = push."]}]}].sort((e,a)=>e.order-a.order);e.s(["allLines",0,function(){return a.flatMap(e=>e.lines.map(a=>({opening:e,line:a})))},"getOpening",0,function(e){return a.find(a=>a.id===e)},"openings",0,a],21086);var t=e.i(5064);let n={1:{label:"Beginner",cls:"bg-green-soft text-green",pips:"●○○"},2:{label:"Intermediate",cls:"bg-gold-soft text-gold",pips:"●●○"},3:{label:"Advanced",cls:"bg-red-soft text-red",pips:"●●●"}};e.s(["default",0,function({level:e,compact:a}){let i=n[e];return(0,t.jsxs)("span",{className:`inline-flex items-center gap-1 text-[11px] px-2 py-0.5 rounded-full font-bold ${i.cls}`,title:i.label,children:[(0,t.jsx)("span",{className:"tracking-tighter",children:i.pips}),!a&&i.label]})}],16095)}]);